window.AUTH=window.AUTH||{};window.AUTH["18-260"]={"d":"18-260","id":"2019/18-260","n":"County of Maui, Hawaii v. Hawaii Wildlife Fund","briefs":[{"k":"petitioner","label":"Brief of petitioner County of Maui, Hawaii","date":"2019-05-09","url":"https://www.supremecourt.gov/DocketPDF/18/18-260/99095/20190509124241199_BriefForPetitioner050919.pdf","side":"pet","n":95},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-05-16","url":"https://www.supremecourt.gov/DocketPDF/18/18-260/100079/20190516161951453_18-260tsacUnitedStates.pdf","side":"us","n":53},{"k":"respondent","label":"Brief of respondents Hawai'i Wildlife Fund, et al.","date":"2019-07-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-260/107959/20190712150847526_2019-7-12%20Respondents%20Brief.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner County of Maui, Hawaii","date":"2019-08-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-260/111957/20190812124630861_18-260ReplyBriefForPetitioner.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=181","tr":true,"items":[{"t":"case","label":"Federal Cases: Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"op":3,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"27, 28"}},{"t":"case","label":"Arkansas v. Oklahoma","cite":"503 U.S. 91","y":1992,"id":"1991/90-1262","sc":1,"sum":"The EPA's action was authorized by the Clean Water Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"3","2":"6, 34"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Catskill Mountains Chapter of Trout Unlimited, Inc. v. City of New York","cite":"273 F.3d 481","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/273/481/","by":{"0":"26, 49"}},{"t":"case","label":"Center for Native Ecosystems v. Cables","cite":"509 F.3d 1310","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/509/1310/","op":2,"by":{"0":"26","2":"37"}},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"op":2,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 22"}},{"t":"case","label":"Concerned Area Residents for the Env’t v. Southview Farm","cite":"34 F.3d 114","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/34/114/","sum":"Holding that flow of pollutants discharged from point sources to navigable waters fell within the Act regardless of whether the pollutants ultimately reached the waters through a point source.","sumSrc":"brief:2","by":{"0":"34","1":"22","2":"19, 38"}},{"t":"case","label":"Cordiano v. Metacon Gun Club, Inc.","cite":"575 F.3d 199","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/575/199/","sum":"Holding that runoff of pollutants from a berm to navigable waters was not a point-source discharge because the berm was not a “confined and discrete conveyance” meeting the point-source definition.","sumSrc":"brief:2","by":{"0":"26, 35, 36, 49","2":"37, 38"}},{"t":"case","label":"Dague v. City of Burlington","cite":"935 F.2d 1343","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/935/1343/","by":{"0":"34"}},{"t":"case","label":"Decker v. Nw. Envtl. Def. Ctr.","cite":"568 U.S. 597","y":2013,"id":"2012/11-338","sc":1,"sum":"The Court found that based on the Clean Water Act, a permit is not necessary for storm water runoff because it is not associated with industrial activity.","sumSrc":"Oyez","by":{"0":"30","2":"39"}},{"t":"case","label":"Director, Office of Workers’ Comp. Programs, Dep’t of Labor v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"EPA v. California ex rel. State Water Res. Control Bd.","cite":"426 U.S. 200","y":1976,"id":"1975/74-1435","sc":1,"op":4,"sum":"Rejecting an interpretation that would facilitate “evasion of the law”.","sumSrc":"opinion","by":{"0":"21, 22, 23, 39","1":"14","2":"3","3":"16"}},{"t":"case","label":"Exxon Corp. v. Train","cite":"554 F.2d 1310","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/554/1310/","by":{"0":"41","1":"16, 17, 18"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"45","2":"44"}},{"t":"case","label":"Greater Yellowstone Coal. v. Lewis","cite":"628 F.3d 1143","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/628/1143/","op":1,"ar":1,"by":{"0":"50"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"42","3":"17"}},{"t":"case","label":"International Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"op":4,"sum":"The Clean Water Act (Act) prohibits the discharge of effluents into navigable waters unless the point source has obtained a permit from the Environmental Protection Agency (EPA). The Act also allows the State in which the point source is located (the \"source State\") to impose more stringent discharge limitations than the federal ones, and even to administer its own permit program if certain requirements are met. In …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 51","2":"56"}},{"t":"case","label":"Kentucky Waterways All. v. Ky. Utils. Co.","cite":"905 F.3d 925","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/925/","op":2,"by":{"0":"5, 26, 34, 37, 44","1":"23","3":"23"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"28","3":"2"}},{"t":"case","label":"League of Wilderness Defs./Blue Mountains Biodiversity Project v. Forsgren","cite":"309 F.3d 1181","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/1181/","by":{"0":"26, 32","2":"37, 40","3":"21"}},{"t":"case","label":"National Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"31, 36"}},{"t":"case","label":"National Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"passim","2":"4, 5, 17","3":"1, 4"}},{"t":"case","label":"National Wildlife Fed’n v. Consumers Power Co.","cite":"862 F.2d 580","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/580/","by":{"0":"35"}},{"t":"case","label":"Natural Res. Def. Council v. EPA","cite":"915 F.2d 1314","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/915/1314/","op":3,"by":{"0":"25, 35"}},{"t":"case","label":"Oregon Nat. Desert Ass’n v. Dombeck","cite":"172 F.3d 1092","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/172/1092/","by":{"0":"25"}},{"t":"case","label":"Oregon Nat. Desert Ass’n v. U.S. Forest Serv.","cite":"550 F.3d 778","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/550/778/","by":{"0":"23, 25, 34","2":"35","3":"9"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"op":13,"ar":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"4, 23, 33, 38, 42","1":"4, 5, 10, 20, 21, 22","2":"2, 3, 11, 19, 20, 21, 45","3":"9"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"0":"31, 38"}},{"t":"case","label":"Sierra Club v. Abston Constr. Co.","cite":"620 F.2d 41","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/620/41/","by":{"0":"26, 50","2":"40"}},{"t":"case","label":"Sierra Club v. El Paso Gold Mines, Inc.","cite":"421 F.3d 1133","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/421/1133/","by":{"0":"34","1":"22","2":"37, 40"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"op":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"0":"3, 27, 45, 52","1":"15, 25","2":"45","3":"2, 18"}},{"t":"case","label":"South Fla. Water Mgmt. Dist. v. Miccosukee Tribe of Indians","cite":"541 U.S. 95","y":2004,"id":"2003/02-626","sc":1,"op":3,"sum":"The Court sent the case back to the district court to consider whether the water conservation area and the canal used to transport the water are distinct. If the district court decides the two are not distinct, then the water district will not need a permit under the Clean Water Act.","sumSrc":"Oyez","by":{"0":"passim","2":"17, 18, 31, 32, 41, 44, 56","3":"5, 6"}},{"t":"case","label":"Trustees for Alaska v. EPA","cite":"749 F.2d 549","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/749/549/","by":{"0":"50"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"19, 32","3":"8"}},{"t":"case","label":"United States v. Ortiz","cite":"427 F.3d 1278","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/427/1278/","by":{"0":"34"}},{"t":"case","label":"United States v. Velsicol Chem. Corp.","cite":"438 F. Supp. 945","y":1976,"court":"W.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./438/945/","by":{"0":"34","1":"22"}},{"t":"case","label":"United States v. Wilson","cite":"133 F.3d 251","y":1997,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/251/","by":{"0":"30"}},{"t":"case","label":"United States ex rel. Tenn. Valley Auth. v. Tenn. Water Quality Control Bd.","cite":"717 F.2d 992","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/717/992/","by":{"0":"26"}},{"t":"case","label":"Upstate Forever v. Kinder Morgan Energy Partners, L.P.","cite":"887 F.3d 637","y":2018,"court":"U.S. Aug. 28","url":"https://www.courtlistener.com/c/F.3d/887/637/","op":2,"by":{"0":"passim","1":"23"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"by":{"0":"37, 38, 46","3":"2, 12"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"op":5,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"20, 27, 45, 49, 52","1":"24, 25","2":"52, 53","3":"1, 2, 18"}},{"t":"case","label":"Village of Oconomowoc Lake v. Dayton Hudson Corp.","cite":"24 F.3d 962","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/24/962/","by":{"0":"50","1":"26","2":"46"}},{"t":"case","label":"Waterkeeper All., Inc. v. EPA","cite":"399 F.3d 486","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/399/486/","by":{"0":"49"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"usc","label":"16 U.S.C. § 1455b","url":"https://www.law.cornell.edu/uscode/text/16/1455b","subs":["(a)(1)","(a)(2)"],"by":{"0":"13, 44, 13"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","subs":["(a)","(a)(1)","(a)(6)","(a)(7)","(b)"],"stext":{"head":"§1251. Congressional declaration of goals and policy","paras":[[0,"(a) Restoration and maintenance of chemical, physical and biological integrity of Nation's waters; national goals for achievement of objective"],[0,"The objective of this chapter is to restore and maintain the chemical, physical, and biological integrity of the Nation's waters. In order to achieve this objective it is hereby declared that, consistent with the provisions of this chapter—"],[1,"(1) it is the national goal that the discharge of pollutants into the navigable waters be eliminated by 1985;"],[1,"(2) it is the national goal that wherever attainable, an interim goal of water quality which provides for the protection and propagation of fish, shellfish, and wildlife and provides for recreation in and on the water be achieved by July 1, 1983;"],[1,"(3) it is the national policy that the discharge of toxic pollutants in toxic amounts be prohibited;"],[1,"(4) it is the national policy that Federal financial assistance be provided to construct publicly owned waste treatment works;"],[1,"(5) it is the national policy that areawide waste treatment management planning processes be developed and implemented to assure adequate control of sources of pollutants in each State;"],[1,"(6) it is the national policy that a major research and demonstration effort be made to develop technology necessary to eliminate the discharge of pollutants into the navigable waters, waters of the contiguous zone, and the oceans; and"],[1,"(7) it is the national policy that programs for the control of nonpoint sources of pollution be developed and implemented in an expeditious manner so as to enable the goals of this chapter to be met through the control of both point and nonpoint sources of pollution."],[0,"(b) Congressional recognition, preservation, and protection of primary responsibilities and rights of States"],[0,"It is the policy of the Congress to recognize, preserve, and protect the primary responsibilities and rights of States to prevent, reduce, and eliminate pollution, to plan the development and use (including restoration, preservation, and enhancement) of land and water resources, and to consult with the Administrator in the exercise of his authority under this chapter. It is the policy of Congress that the States manage the construction grant program under this chapter and implement the permit programs under sections 1342 and 1344 of this title. It is further the policy of the Congress to support and aid research relating to the prevention, reduction, and elimination of pollution and to provide Federal technical services and financial aid to State and interstate agencies and municipalities in connection with the prevention, reduction, and elimination of pollution."],[0,"(c) Congressional policy toward Presidential activities with foreign countries"],[0,"It is further the policy of Congress that the President, acting through the Secretary of State and such national and international organizations as he determines appropriate, shall take such action as may be necessary to insure that to the fullest extent possible all foreign countries shall take meaningful action for the prevention, reduction, and elimination of pollution in their waters and in international waters and for the achievement of goals regarding the elimination of discharge of pollutants and the improvement of water quality to at least the same extent as the United States does under its laws."],[0,"(d) Administrator of Environmental Protection Agency to administer chapter"],[0,"Except as otherwise expressly provided in this chapter, the Administrator of the Environmental Protection Agency (hereinafter in this chapter called \"Administrator\") shall administer this chapter."],[0,"(e) Public participation in development, revision, and enforcement of any regulation, etc."],[0,"Public participation in the development, revision, and enforcement of any regulation, standard, effluent limitation, plan, or program established by the Administrator or any State under this chapter shall be provided for, encouraged, and assisted by the Administrator and the States. The Administrator, in cooperation with the States, shall develop and publish regulations specifying minimum guidelines for public participation in such processes."],[0,"(f) Procedures utilized for implementing chapter"],[0,"It is the national policy that to the maximum extent possible the procedures utilized for implementing this chapter shall encourage the drastic minimization of paperwork and interagency decision procedures, and the best use of available manpower and funds, so as to prevent needless duplication and unnecessary delays at all levels of government."],[0,"(g) Authority of States over water"],[0,"It is the policy of Congress that the authority of each State to allocate quantities of water within its jurisdiction shall not be superseded, abrogated or otherwise impaired by this chapter. It is the further policy of Congress that nothing in this chapter shall be construed to supersede or abrogate rights to quantities of water which have been established by any State. Federal agencies shall co-operate with State and local agencies to develop comprehensive solutions to prevent, reduce and eliminate pollution in concert with programs for managing water resources."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1251?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1251. Congressional declaration of goals and policy","tname":"Navigation and Navigable Waters","by":{"0":"9, 41, 1, 9, 37, 37, 1, 9, 11, 24, 42, 1, 4, 9, 42","3":"2, 10, 21"}},{"t":"usc","label":"33 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/33/1252","subs":["(a)"],"stext":{"head":"§1252. Comprehensive programs for water pollution control","paras":[[0,"(a) Preparation and development"],[0,"The Administrator shall, after careful investigation, and in cooperation with other Federal agencies, State water pollution control agencies, interstate agencies, and the municipalities and industries involved, prepare or develop comprehensive programs for preventing, reducing, or eliminating the pollution of the navigable waters and ground waters and improving the sanitary condition of surface and underground waters. In the development of such comprehensive programs due regard shall be given to the improvements which are necessary to conserve such waters for the protection and propagation of fish and aquatic life and wildlife, recreational purposes, and the withdrawal of such waters for public water supply, agricultural, industrial, and other purposes. For the purpose of this section, the Administrator is authorized to make joint investigations with any such agencies of the condition of any waters in any State or States, and of the discharges of any sewage, industrial wastes, or substance which may adversely affect such waters."],[0,"(b) Planning for reservoirs; storage for regulation of streamflow"],[0,"(1) In the survey or planning of any reservoir by the Corps of Engineers, Bureau of Reclamation, or other Federal agency, consideration shall be given to inclusion of storage for regulation of streamflow, except that any such storage and water releases shall not be provided as a substitute for adequate treatment or other methods of controlling waste at the source."],[0,"(2) The need for and the value of storage for regulation of streamflow (other than for water quality) including but not limited to navigation, salt water intrusion, recreation, esthetics, and fish and wildlife, shall be determined by the Corps of Engineers, Bureau of Reclamation, or other Federal agencies."],[0,"(3) The need for, the value of, and the impact of, storage for water quality control shall be determined by the Administrator, and his views on these matters shall be set forth in any report or presentation to Congress proposing authorization or construction of any reservoir including such storage."],[0,"(4) The value of such storage shall be taken into account in determining the economic value of the entire project of which it is a part, and costs shall be allocated to the purpose of regulation of streamflow in a manner which will insure that all project purposes, share equitably in the benefit of multiple-purpose construction."],[0,"(5) Costs of regulation of streamflow features incorporated in any Federal reservoir or other impoundment under the provisions of this chapter shall be determined and the beneficiaries identified and if the benefits are widespread or national in scope, the costs of such features shall be nonreimbursable."],[0,"(6) No license granted by the Federal Energy Regulatory Commission for a hydroelectric power project shall include storage for regulation of streamflow for the purpose of water quality control unless the Administrator shall recommend its inclusion and such reservoir storage capacity shall not exceed such proportion of the total storage required for the water quality control plan as the drainage area of such reservoir bears to the drainage area of the river basin or basins involved in such water quality control plan."],[0,"(c) Basins; grants to State agencies"],[0,"(1) The Administrator shall, at the request of the Governor of a State, or a majority of the Governors when more than one State is involved, make a grant to pay not to exceed 50 per centum of the administrative expenses of a planning agency for a period not to exceed three years, which period shall begin after October 18, 1972, if such agency provides for adequate representation of appropriate State, interstate, local, or (when appropriate) international interests in the basin or portion thereof involved and is capable of developing an effective, comprehensive water quality control plan for a basin or portion thereof."],[0,"(2) Each planning agency receiving a grant under this subsection shall develop a comprehensive pollution control plan for the basin or portion thereof which—"],[1,"(A) is consistent with any applicable water quality standards effluent and other limitations, and thermal discharge regulations established pursuant to current law within the basin;"],[1,"(B) recommends such treatment works as will provide the most effective and economical means of collection, storage, treatment, and elimination of pollutants and recommends means to encourage both municipal and industrial use of such works;"],[1,"(C) recommends maintenance and improvement of water quality within the basin or portion thereof and recommends methods of adequately financing those facilities as may be necessary to implement the plan; and"],[1,"(D) as appropriate, is developed in cooperation with, and is consistent with any comprehensive plan prepared by the Water Resources Council, any areawide waste management plans developed pursuant to section 1288 of this title, and any State plan developed pursuant to section 1313(e) of this title."],[0,"(3) For the purposes of this subsection the term \"basin\" includes, but is not limited to, rivers and their tributaries, streams, coastal waters, sounds, estuaries, bays, lakes, and portions thereof as well as the lands drained thereby."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1252. Comprehensive programs for water pollution control","tname":"Navigation and Navigable Waters","by":{"0":"10"}},{"t":"usc","label":"33 U.S.C. § 1256","url":"https://www.law.cornell.edu/uscode/text/33/1256","subs":["(e)"],"by":{"0":"10"}},{"t":"usc","label":"33 U.S.C. § 1285","url":"https://www.law.cornell.edu/uscode/text/33/1285","subs":["(j)"],"stext":{"head":"§1285. Allotment of grant funds","paras":[[0,"(a) Funds for fiscal years during period June 30, 1972, and September 30, 1977; determination of amount"],[0,"Sums authorized to be appropriated pursuant to section 1287 of this title for each fiscal year beginning after June 30, 1972, and before September 30, 1977, shall be allotted by the Administrator not later than the January 1st immediately preceding the beginning of the fiscal year for which authorized, except that the allotment for fiscal year 1973 shall be made not later than 30 days after October 18, 1972. Such sums shall be allotted among the States by the Administrator in accordance with regulations promulgated by him, in the ratio that the estimated cost of constructing all needed publicly owned treatment works in each State bears to the estimated cost of construction of all needed publicly owned treatment works in all of the States. For the fiscal years ending June 30, 1973, and June 30, 1974, such ratio shall be determined on the basis of table III of House Public Works Committee Print No. 92–50. For the fiscal year ending June 30, 1975, such ratio shall be determined one-half on the basis of table I of House Public Works Committee Print Numbered 93–28 and one-half on the basis of table II of such print, except that no State shall receive an allotment less than that which it received for the fiscal year ending June 30, 1972, as set forth in table III of such print. Allotments for fiscal years which begin after the fiscal year ending June 30, 1975, shall be made only in accordance with a revised cost estimate made and submitted to Congress in accordance with section 1375(b) of this title and only after such revised cost estimate shall have been approved by law specifically enacted after October 18, 1972."],[0,"(b) Availability and use of funds allotted for fiscal years during period June 30, 1972, and September 30, 1977; reallotment"],[0,"(1) Any sums allotted to a State under subsection (a) shall be available for obligation under section 1283 of this title on and after the date of such allotment. Such sums shall continue available for obligation in such State for a period of one year after the close of the fiscal year for which such sums are authorized. Any amounts so allotted which are not obligated by the end of such one-year period shall be immediately reallotted by the Administrator, in accordance with regulations promulgated by him, generally on the basis of the ratio used in making the last allotment of sums under this section. Such reallotted sums shall be added to the last allotments made to the States. Any sum made available to a State by reallotment under this subsection shall be in addition to any funds otherwise allotted to such State for grants under this subchapter during any fiscal year."],[0,"(2) Any sums which have been obligated under section 1283 of this title and which are released by the payment of the final voucher for the project shall be immediately credited to the State to which such sums were last allotted. Such released sums shall be added to the amounts last allotted to such State and shall be immediately available for obligation in the same manner and to the same extent as such last allotment."],[0,"(c) Funds for fiscal years during period October 1, 1977, and September 30, 1981; funds for fiscal years 1982 to 1990; determination of amount"],[0,"(1) Sums authorized to be appropriated pursuant to section 1287 of this title for the fiscal years during the period beginning October 1, 1977, and ending September 30, 1981, shall be allotted for each such year by the Administrator not later than the tenth day which begins after December 27, 1977. Notwithstanding any other provision of law, sums authorized for the fiscal years ending September 30, 1978, September 30, 1979, September 30, 1980, and September 30, 1981, shall be allotted in accordance with table 3 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives."],[0,"(2) Sums authorized to be appropriated pursuant to section 1287 of this title for the fiscal years 1982, 1983, 1984, and 1985 shall be allotted for each such year by the Administrator not later than the tenth day which begins after December 29, 1981. Notwithstanding any other provision of law, sums authorized for the fiscal year ending September 30, 1982, shall be allotted in accordance with table 3 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives. Sums authorized for the fiscal years ending September 30, 1983, September 30, 1984, September 30, 1985, and September 30, 1986, shall be allotted in accordance with the following table:"],[0,"(3) Fiscal years 1987–1990.—Sums authorized to be appropriated pursuant to section 1287 of this title for the fiscal years 1987, 1988, 1989, and 1990 shall be allotted for each such year by the Administrator not later than the 10th day which begins after February 4, 1987. Sums authorized for such fiscal years shall be allotted in accordance with the following table:"],[0,"(d) Availability and use of funds; reallotment"],[0,"Sums allotted to the States for a fiscal year shall remain available for obligation for the fiscal year for which authorized and for the period of the next succeeding twelve months. The amount of any allotment not obligated by the end of such twenty-four-month period shall be immediately reallotted by the Administrator on the basis of the same ratio as applicable to sums allotted for the then current fiscal year, except that none of the funds reallotted by the Administrator for fiscal year 1978 and for fiscal years thereafter shall be allotted to any State which failed to obligate any of the funds being reallotted. Any sum made available to a State by reallotment under this subsection shall be in addition to any funds otherwise allotted to such State for grants under this subchapter during any fiscal year."],[0,"(e) Minimum allotment; additional appropriations; ratio of amount available"],[0,"For the fiscal years 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, and 1990, no State shall receive less than one-half of 1 per centum of the total allotment under subsection (c) of this section, except that in the case of Guam, Virgin Islands, American Samoa, and the Trust Territories not more than thirty-three one-hundredths of 1 per centum in the aggregate shall be allotted to all four of these jurisdictions. For the purpose of carrying out this subsection there are authorized to be appropriated, subject to such amounts as are provided in appropriation Acts, not to exceed $75,000,000 for each of fiscal years 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, and 1990. If for any fiscal year the amount appropriated under authority of this subsection is less than the amount necessary to carry out this subsection, the amount each State receives under this subsection for such year shall bear the same ratio to the amount such State would have received under this subsection in such year if the amount necessary to carry it out had been appropriated as the amount appropriated for such year bears to the amount necessary to carry out this subsection for such year."],[0,"(f) Omitted"],[0,"(g) Reservation of funds; State management assistance"],[0,"(1) The Administrator is authorized to reserve each fiscal year not to exceed 2 per centum of the amount authorized under section 1287 of this title for purposes of the allotment made to each State under this section on or after October 1, 1977, except in the case of any fiscal year beginning on or after October 1, 1981, and ending before October 1, 1994, in which case the percentage authorized to be reserved shall not exceed 4 per centum.2 or $400,000 whichever amount is the greater. Sums so reserved shall be available for making grants to such State under paragraph (2) of this subsection for the same period as sums are available from such allotment under subsection (d) of this section, and any such grant shall be available for obligation only during such period. Any grant made from sums reserved under this subsection which has not been obligated by the end of the period for which available shall be added to the amount last allotted to such State under this section and shall be immediately available for obligation in the same manner and to the same extent as such last allotment. Sums authorized to be reserved by this paragraph shall be in addition to and not in lieu of any other funds which may be authorized to carry out this subsection."],[0,"(2) The Administrator is authorized to grant to any State from amounts reserved to such State under this subsection, the reasonable costs of administering any aspects of sections 1281, 1283, 1284, and 1292 of this title the responsibility for administration of which the Administrator has delegated to such State. The Administrator may increase such grant to take into account the reasonable costs of administering an approved program under section 1342 or 1344 of this title, administering a state-wide waste treatment management planning program under section 1288(b)(4) of this title, and managing waste treatment construction grants for small communities."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1285?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1285. Allotment of grant funds","tname":"Navigation and Navigable Waters","by":{"0":"11"}},{"t":"usc","label":"33 U.S.C. § 1298","url":"https://www.law.cornell.edu/uscode/text/33/1298","subs":["(b)"],"by":{"0":"13"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","subs":["(a)"],"stext":{"head":"§1311. Effluent limitations","paras":[[0,"(a) Illegality of pollutant discharges except in compliance with law"],[0,"Except as in compliance with this section and sections 1312, 1316, 1317, 1328, 1342, and 1344 of this title, the discharge of any pollutant by any person shall be unlawful."],[0,"(b) Timetable for achievement of objectives"],[0,"In order to carry out the objective of this chapter there shall be achieved—"],[1,"(1)(A) not later than July 1, 1977, effluent limitations for point sources, other than publicly owned treatment works, (i) which shall require the application of the best practicable control technology currently available as defined by the Administrator pursuant to section 1314(b) of this title, or (ii) in the case of a discharge into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, which shall require compliance with any applicable pretreatment requirements and any requirements under section 1317 of this title; and"],[1,"(B) for publicly owned treatment works in existence on July 1, 1977, or approved pursuant to section 1283 of this title prior to June 30, 1974 (for which construction must be completed within four years of approval), effluent limitations based upon secondary treatment as defined by the Administrator pursuant to section 1314(d)(1) of this title; or,"],[1,"(C) not later than July 1, 1977, any more stringent limitation, including those necessary to meet water quality standards, treatment standards, or schedules of compliance, established pursuant to any State law or regulations (under authority preserved by section 1370 of this title) or any other Federal law or regulation, or required to implement any applicable water quality standard established pursuant to this chapter."],[1,"(2)(A) for pollutants identified in subparagraphs (C), (D), and (F) of this paragraph, effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which (i) shall require application of the best available technology economically achievable for such category or class, which will result in reasonable further progress toward the national goal of eliminating the discharge of all pollutants, as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, which such effluent limitations shall require the elimination of discharges of all pollutants if the Administrator finds, on the basis of information available to him (including information developed pursuant to section 1325 of this title), that such elimination is technologically and economically achievable for a category or class of point sources as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, or (ii) in the case of the introduction of a pollutant into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, shall require compliance with any applicable pretreatment requirements and any other requirement under section 1317 of this title;"],[1,"(B) Repealed. Pub. L. 97–117, §21(b), Dec. 29, 1981, 95 Stat. 1632."],[1,"(C) with respect to all toxic pollutants referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(D) for all toxic pollutants listed under paragraph (1) of subsection (a) of section 1317 of this title which are not referred to in subparagraph (C) of this paragraph compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable, but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(E) as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989, compliance with effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which in the case of pollutants identified pursuant to section 1314(a)(4) of this title shall require application of the best conventional pollutant control technology as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(4) of this title; and"],[1,"(F) for all pollutants (other than those subject to subparagraphs (C), (D), or (E) of this paragraph) compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than 3 years after the date such limitations are established, and in no case later than March 31, 1989."],[1,"(3)(A) for effluent limitations under paragraph (1)(A)(i) of this subsection promulgated after January 1, 1982, and requiring a level of control substantially greater or based on fundamentally different control technology than under permits for an industrial category issued before such date, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989; and"],[1,"(B) for any effluent limitation in accordance with paragraph (1)(A)(i), (2)(A)(i), or (2)(E) of this subsection established only on the basis of section 1342(a)(1) of this title in a permit issued after February 4, 1987, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are established, and in no case later than March 31, 1989."],[0,"(c) Modification of timetable"],[0,"The Administrator may modify the requirements of subsection (b)(2)(A) of this section with respect to any point source for which a permit application is filed after July 1, 1977, upon a showing by the owner or operator of such point source satisfactory to the Administrator that such modified requirements (1) will represent the maximum use of technology within the economic capability of the owner or operator; and (2) will result in reasonable further progress toward the elimination of the discharge of pollutants."],[0,"(d) Review and revision of effluent limitations"],[0,"Any effluent limitation required by paragraph (2) of subsection (b) of this section shall be reviewed at least every five years and, if appropriate, revised pursuant to the procedure established under such paragraph."],[0,"(e) All point discharge source application of effluent limitations"],[0,"Effluent limitations established pursuant to this section or section 1312 of this title shall be applied to all point sources of discharge of pollutants in accordance with the provisions of this chapter."],[0,"(f) Illegality of discharge of radiological, chemical, or biological warfare agents, high-level radioactive waste, or medical waste"],[0,"Notwithstanding any other provisions of this chapter it shall be unlawful to discharge any radiological, chemical, or biological warfare agent, any high-level radioactive waste, or any medical waste, into the navigable waters."],[0,"(g) Modifications for certain nonconventional pollutants"],[0,"(1) General authority"],[1,"The Administrator, with the concurrence of the State, may modify the requirements of subsection (b)(2)(A) of this section with respect to the discharge from any point source of ammonia, chlorine, color, iron, and total phenols (4AAP) (when determined by the Administrator to be a pollutant covered by subsection (b)(2)(F)) and any other pollutant which the Administrator lists under paragraph (4) of this subsection."],[0,"(2) Requirements for granting modifications"],[1,"A modification under this subsection shall be granted only upon a showing by the owner or operator of a point source satisfactory to the Administrator that—"],[2,"(A) such modified requirements will result at a minimum in compliance with the requirements of subsection (b)(1)(A) or (C) of this section, whichever is applicable;"],[2,"(B) such modified requirements will not result in any additional requirements on any other point or nonpoint source; and"],[2,"(C) such modification will not interfere with the attainment or maintenance of that water quality which shall assure protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish, and wildlife, and allow recreational activities, in and on the water and such modification will not result in the discharge of pollutants in quantities which may reasonably be anticipated to pose an unacceptable risk to human health or the environment because of bioaccumulation, persistency in the environment, acute toxicity, chronic toxicity (including carcinogenicity, mutagenicity or teratogenicity), or synergistic propensities."],[0,"(3) Limitation on authority to apply for subsection (c) modification"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1311?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1311. Effluent limitations","tname":"Navigation and Navigable Waters","by":{"0":"passim","3":"15, 15"}},{"t":"usc","label":"33 U.S.C. § 1314","url":"https://www.law.cornell.edu/uscode/text/33/1314","subs":["(f)","(f)(1)","(f)(2)(D)"],"stext":{"head":"§1314. Information and guidelines","paras":[[0,"(a) Criteria development and publication"],[0,"(1) The Administrator, after consultation with appropriate Federal and State agencies and other interested persons, shall develop and publish, within one year after October 18, 1972 (and from time to time thereafter revise) criteria for water quality accurately reflecting the latest scientific knowledge (A) on the kind and extent of all identifiable effects on health and welfare including, but not limited to, plankton, fish, shellfish, wildlife, plant life, shorelines, beaches, esthetics, and recreation which may be expected from the presence of pollutants in any body of water, including ground water; (B) on the concentration and dispersal of pollutants, or their byproducts, through biological, physical, and chemical processes; and (C) on the effects of pollutants on biological community diversity, productivity, and stability, including information on the factors affecting rates of eutrophication and rates of organic and inorganic sedimentation for varying types of receiving waters."],[0,"(2) The Administrator, after consultation with appropriate Federal and State agencies and other interested persons, shall develop and publish, within one year after October 18, 1972 (and from time to time thereafter revise) information (A) on the factors necessary to restore and maintain the chemical, physical, and biological integrity of all navigable waters, ground waters, waters of the contiguous zone, and the oceans; (B) on the factors necessary for the protection and propagation of shellfish, fish, and wildlife for classes and categories of receiving waters and to allow recreational activities in and on the water; and (C) on the measurement and classification of water quality; and (D) for the purpose of section 1313 of this title, on and the identification of pollutants suitable for maximum daily load measurement correlated with the achievement of water quality objectives."],[0,"(3) Such criteria and information and revisions thereof shall be issued to the States and shall be published in the Federal Register and otherwise made available to the public."],[0,"(4) The Administrator shall, within 90 days after December 27, 1977, and from time to time thereafter, publish and revise as appropriate information identifying conventional pollutants, including but not limited to, pollutants classified as biological oxygen demanding, suspended solids, fecal coliform, and pH. The thermal component of any discharge shall not be identified as a conventional pollutant under this paragraph."],[0,"(5)(A) The Administrator, to the extent practicable before consideration of any request under section 1311(g) of this title and within six months after December 27, 1977, shall develop and publish information on the factors necessary for the protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish and wildlife, and to allow recreational activities, in and on the water."],[0,"(B) The Administrator, to the extent practicable before consideration of any application under section 1311(h) of this title and within six months after December 27, 1977, shall develop and publish information on the factors necessary for the protection of public water supplies, and the protection and propagation of a balanced indigenous population of shellfish, fish and wildlife, and to allow recreational activities, in and on the water."],[0,"(6) The Administrator shall, within three months after December 27, 1977, and annually thereafter, for purposes of section 1311(h) of this title publish and revise as appropriate information identifying each water quality standard in effect under this chapter or State law, the specific pollutants associated with such water quality standard, and the particular waters to which such water quality standard applies."],[0,"(7) Guidance to states.—The Administrator, after consultation with appropriate State agencies and on the basis of criteria and information published under paragraphs (1) and (2) of this subsection, shall develop and publish, within 9 months after February 4, 1987, guidance to the States on performing the identification required by subsection (l)(1) of this section."],[0,"(8) Information on water quality criteria.—The Administrator, after consultation with appropriate State agencies and within 2 years after February 4, 1987, shall develop and publish information on methods for establishing and measuring water quality criteria for toxic pollutants on other bases than pollutant-by-pollutant criteria, including biological monitoring and assessment methods."],[0,"(9) Revised criteria for coastal recreation waters.—"],[1,"(A) In general.—Not later than 5 years after October 10, 2000, after consultation and in cooperation with appropriate Federal, State, tribal, and local officials (including local health officials), the Administrator shall publish new or revised water quality criteria for pathogens and pathogen indicators (including a revised list of testing methods, as appropriate), based on the results of the studies conducted under section 1254(v) of this title, for the purpose of protecting human health in coastal recreation waters."],[1,"(B) Reviews.—Not later than the date that is 5 years after the date of publication of water quality criteria under this paragraph, and at least once every 5 years thereafter, the Administrator shall review and, as necessary, revise the water quality criteria."],[0,"(b) Effluent limitation guidelines"],[0,"For the purpose of adopting or revising effluent limitations under this chapter the Administrator shall, after consultation with appropriate Federal and State agencies and other interested persons, publish within one year of October 18, 1972, regulations, providing guidelines for effluent limitations, and, at least annually thereafter, revise, if appropriate, such regulations. Such regulations shall—"],[1,"(1)(A) identify, in terms of amounts of constituents and chemical, physical, and biological characteristics of pollutants, the degree of effluent reduction attainable through the application of the best practicable control technology currently available for classes and categories of point sources (other than publicly owned treatment works); and"],[1,"(B) specify factors to be taken into account in determining the control measures and practices to be applicable to point sources (other than publicly owned treatment works) within such categories or classes. Factors relating to the assessment of best practicable control technology currently available to comply with subsection (b)(1) of section 1311 of this title shall include consideration of the total cost of application of technology in relation to the effluent reduction benefits to be achieved from such application, and shall also take into account the age of equipment and facilities involved, the process employed, the engineering aspects of the application of various types of control techniques, process changes, non-water quality environmental impact (including energy requirements), and such other factors as the Administrator deems appropriate;"],[1,"(2)(A) identify, in terms of amounts of constituents and chemical, physical, and biological characteristics of pollutants, the degree of effluent reduction attainable through the application of the best control measures and practices achievable including treatment techniques, process and procedure innovations, operating methods, and other alternatives for classes and categories of point sources (other than publicly owned treatment works); and"],[1,"(B) specify factors to be taken into account in determining the best measures and practices available to comply with subsection (b)(2) of section 1311 of this title to be applicable to any point source (other than publicly owned treatment works) within such categories or classes. Factors relating to the assessment of best available technology shall take into account the age of equipment and facilities involved, the process employed, the engineering aspects of the application of various types of control techniques, process changes, the cost of achieving such effluent reduction, non-water quality environmental impact (including energy requirements), and such other factors as the Administrator deems appropriate;"],[1,"(3) identify control measures and practices available to eliminate the discharge of pollutants from categories and classes of point sources, taking into account the cost of achieving such elimination of the discharge of pollutants; and"],[1,"(4)(A) identify, in terms of amounts of constituents and chemical, physical, and biological characteristics of pollutants, the degree of effluent reduction attainable through the application of the best conventional pollutant control technology (including measures and practices) for classes and categories of point sources (other than publicly owned treatment works); and"],[1,"(B) specify factors to be taken into account in determining the best conventional pollutant control technology measures and practices to comply with section 1311(b)(2)(E) of this title to be applicable to any point source (other than publicly owned treatment works) within such categories or classes. Factors relating to the assessment of best conventional pollutant control technology (including measures and practices) shall include consideration of the reasonableness of the relationship between the costs of attaining a reduction in effluents and the effluent reduction benefits derived, and the comparison of the cost and level of reduction of such pollutants from the discharge from publicly owned treatment works to the cost and level of reduction of such pollutants from a class or category of industrial sources, and shall take into account the age of equipment and facilities involved, the process employed, the engineering aspects of the application of various types of control techniques, process changes, non-water quality environmental impact (including energy requirements), and such other factors as the Administrator deems appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1314?type=usc&year=mostrecent&link-type=html"},"head":"§1314. Information and guidelines","tname":"Navigation and Navigable Waters","by":{"0":"11","3":"15, 14, 15"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(c)","(d)"],"stext":{"head":"§1319. Enforcement","paras":[[0,"(a) State enforcement; compliance orders"],[0,"(1) Whenever, on the basis of any information available to him, the Administrator finds that any person is in violation of any condition or limitation which implements section 1311, 1312, 1316, 1317, 1318, 1328, or 1345 of this title in a permit issued by a State under an approved permit program under section 1342 or 1344 of this title he shall proceed under his authority in paragraph (3) of this subsection or he shall notify the person in alleged violation and such State of such finding. If beyond the thirtieth day after the Administrator's notification the State has not commenced appropriate enforcement action, the Administrator shall issue an order requiring such person to comply with such condition or limitation or shall bring a civil action in accordance with subsection (b) of this section."],[0,"(2) Whenever, on the basis of information available to him, the Administrator finds that violations of permit conditions or limitations as set forth in paragraph (1) of this subsection are so widespread that such violations appear to result from a failure of the State to enforce such permit conditions or limitations effectively, he shall so notify the State. If the Administrator finds such failure extends beyond the thirtieth day after such notice, he shall give public notice of such finding. During the period beginning with such public notice and ending when such State satisfies the Administrator that it will enforce such conditions and limitations (hereafter referred to in this section as the period of \"federally assumed enforcement\"), except where an extension has been granted under paragraph (5)(B) of this subsection, the Administrator shall enforce any permit condition or limitation with respect to any person—"],[1,"(A) by issuing an order to comply with such condition or limitation, or"],[1,"(B) by bringing a civil action under subsection (b) of this section."],[0,"(3) Whenever on the basis of any information available to him the Administrator finds that any person is in violation of section 1311, 1312, 1316, 1317, 1318, 1322(p), 1328, or 1345 of this title, or is in violation of any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by him or by a State or in a permit issued under section 1344 of this title by a State, he shall issue an order requiring such person to comply with such section or requirement, or he shall bring a civil action in accordance with subsection (b) of this section."],[0,"(4) A copy of any order issued under this subsection shall be sent immediately by the Administrator to the State in which the violation occurs and other affected States. In any case in which an order under this subsection (or notice to a violator under paragraph (1) of this subsection) is issued to a corporation, a copy of such order (or notice) shall be served on any appropriate corporate officers. An order issued under this subsection relating to a violation of section 1318 of this title shall not take effect until the person to whom it is issued has had an opportunity to confer with the Administrator concerning the alleged violation."],[0,"(5)(A) Any order issued under this subsection shall be by personal service, shall state with reasonable specificity the nature of the violation, and shall specify a time for compliance not to exceed thirty days in the case of a violation of an interim compliance schedule or operation and maintenance requirement and not to exceed a time the Administrator determines to be reasonable in the case of a violation of a final deadline, taking into account the seriousness of the violation and any good faith efforts to comply with applicable requirements."],[0,"(B) The Administrator may, if he determines (i) that any person who is a violator of, or any person who is otherwise not in compliance with, the time requirements under this chapter or in any permit issued under this chapter, has acted in good faith, and has made a commitment (in the form of contracts or other securities) of necessary resources to achieve compliance by the earliest possible date after July 1, 1977, but not later than April 1, 1979; (ii) that any extension under this provision will not result in the imposition of any additional controls on any other point or nonpoint source; (iii) that an application for a permit under section 1342 of this title was filed for such person prior to December 31, 1974; and (iv) that the facilities necessary for compliance with such requirements are under construction, grant an extension of the date referred to in section 1311(b)(1)(A) of this title to a date which will achieve compliance at the earliest time possible but not later than April 1, 1979."],[0,"(6) Whenever, on the basis of information available to him, the Administrator finds (A) that any person is in violation of section 1311(b)(1)(A) or (C) of this title, (B) that such person cannot meet the requirements for a time extension under section 1311(i)(2) of this title, and (C) that the most expeditious and appropriate means of compliance with this chapter by such person is to discharge into a publicly owned treatment works, then, upon request of such person, the Administrator may issue an order requiring such person to comply with this chapter at the earliest date practicable, but not later than July 1, 1983, by discharging into a publicly owned treatment works if such works concur with such order. Such order shall include a schedule of compliance."],[0,"(b) Civil actions"],[0,"The Administrator is authorized to commence a civil action for appropriate relief, including a permanent or temporary injunction, for any violation for which he is authorized to issue a compliance order under subsection (a) of this section. Any action under this subsection may be brought in the district court of the United States for the district in which the defendant is located or resides or is doing business, and such court shall have jurisdiction to restrain such violation and to require compliance. Notice of the commencement of such action shall be given immediately to the appropriate State."],[0,"(c) Criminal penalties"],[0,"(1) Negligent violations"],[1,"Any person who—"],[2,"(A) negligently violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) negligently introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in any permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $2,500 nor more than $25,000 per day of violation, or by imprisonment for not more than 1 year, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $50,000 per day of violation, or by imprisonment of not more than 2 years, or by both."],[0,"(2) Knowing violations"],[1,"Any person who—"],[2,"(A) knowingly violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) knowingly introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in a permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $5,000 nor more than $50,000 per day of violation, or by imprisonment for not more than 3 years, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $100,000 per day of violation, or by imprisonment of not more than 6 years, or by both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1319?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1319. Enforcement","tname":"Navigation and Navigable Waters","by":{"0":"37, 37"}},{"t":"usc","label":"33 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/33/1321","subs":["(a)(2)","(b)"],"by":{"0":"44, 44"}},{"t":"usc","label":"33 U.S.C. § 1329","url":"https://www.law.cornell.edu/uscode/text/33/1329","subs":["(b)","(b)(1)","(i)"],"stext":{"head":"§1329. Nonpoint source management programs","paras":[[0,"(a) State assessment reports"],[0,"(1) Contents"],[1,"The Governor of each State shall, after notice and opportunity for public comment, prepare and submit to the Administrator for approval, a report which—"],[2,"(A) identifies those navigable waters within the State which, without additional action to control nonpoint sources of pollution, cannot reasonably be expected to attain or maintain applicable water quality standards or the goals and requirements of this chapter;"],[2,"(B) identifies those categories and subcategories of nonpoint sources or, where appropriate, particular nonpoint sources which add significant pollution to each portion of the navigable waters identified under subparagraph (A) in amounts which contribute to such portion not meeting such water quality standards or such goals and requirements;"],[2,"(C) describes the process, including intergovernmental coordination and public participation, for identifying best management practices and measures to control each category and subcategory of nonpoint sources and, where appropriate, particular nonpoint sources identified under subparagraph (B) and to reduce, to the maximum extent practicable, the level of pollution resulting from such category, subcategory, or source; and"],[2,"(D) identifies and describes State and local programs for controlling pollution added from nonpoint sources to, and improving the quality of, each such portion of the navigable waters, including but not limited to those programs which are receiving Federal assistance under subsections (h) and (i)."],[0,"(2) Information used in preparation"],[1,"In developing the report required by this section, the State (A) may rely upon information developed pursuant to sections 1288, 1313(e), 1314(f), 1315(b), and 1324 of this title, and other information as appropriate, and (B) may utilize appropriate elements of the waste treatment management plans developed pursuant to sections 1288(b) and 1313 of this title, to the extent such elements are consistent with and fulfill the requirements of this section."],[0,"(b) State management programs"],[0,"(1) In general"],[1,"The Governor of each State, for that State or in combination with adjacent States, shall, after notice and opportunity for public comment, prepare and submit to the Administrator for approval a management program which such State proposes to implement in the first four fiscal years beginning after the date of submission of such management program for controlling pollution added from nonpoint sources to the navigable waters within the State and improving the quality of such waters."],[0,"(2) Specific contents"],[1,"Each management program proposed for implementation under this subsection shall include each of the following:"],[2,"(A) An identification of the best management practices and measures which will be undertaken to reduce pollutant loadings resulting from each category, subcategory, or particular nonpoint source designated under paragraph (1)(B), taking into account the impact of the practice on ground water quality."],[2,"(B) An identification of programs (including, as appropriate, nonregulatory or regulatory programs for enforcement, technical assistance, financial assistance, education, training, technology transfer, and demonstration projects) to achieve implementation of the best management practices by the categories, subcategories, and particular nonpoint sources designated under subparagraph (A)."],[2,"(C) A schedule containing annual milestones for (i) utilization of the program implementation methods identified in subparagraph (B), and (ii) implementation of the best management practices identified in subparagraph (A) by the categories, subcategories, or particular nonpoint sources designated under paragraph (1)(B). Such schedule shall provide for utilization of the best management practices at the earliest practicable date."],[2,"(D) A certification of the attorney general of the State or States (or the chief attorney of any State water pollution control agency which has independent legal counsel) that the laws of the State or States, as the case may be, provide adequate authority to implement such management program or, if there is not such adequate authority, a list of such additional authorities as will be necessary to implement such management program. A schedule and commitment by the State or States to seek such additional authorities as expeditiously as practicable."],[2,"(E) Sources of Federal and other assistance and funding (other than assistance provided under subsections (h) and (i)) which will be available in each of such fiscal years for supporting implementation of such practices and measures and the purposes for which such assistance will be used in each of such fiscal years."],[2,"(F) An identification of Federal financial assistance programs and Federal development projects for which the State will review individual assistance applications or development projects for their effect on water quality pursuant to the procedures set forth in Executive Order 12372 as in effect on September 17, 1983, to determine whether such assistance applications or development projects would be consistent with the program prepared under this subsection; for the purposes of this subparagraph, identification shall not be limited to the assistance programs or development projects subject to Executive Order 12372 but may include any programs listed in the most recent Catalog of Federal Domestic Assistance which may have an effect on the purposes and objectives of the State's nonpoint source pollution management program."],[0,"(3) Utilization of local and private experts"],[1,"In developing and implementing a management program under this subsection, a State shall, to the maximum extent practicable, involve local public and private agencies and organizations which have expertise in control of nonpoint sources of pollution."],[0,"(4) Development on watershed basis"],[1,"A State shall, to the maximum extent practicable, develop and implement a management program under this subsection on a watershed-by-watershed basis within such State."],[0,"(c) Administrative provisions"],[0,"(1) Cooperation requirement"],[1,"Any report required by subsection (a) and any management program and report required by subsection (b) shall be developed in cooperation with local, substate regional, and interstate entities which are actively planning for the implementation of nonpoint source pollution controls and have either been certified by the Administrator in accordance with section 1288 of this title, have worked jointly with the State on water quality management planning under section 1285(j) of this title, or have been designated by the State legislative body or Governor as water quality management planning agencies for their geographic areas."],[0,"(2) Time period for submission of reports and management programs"],[1,"Each report and management program shall be submitted to the Administrator during the 18-month period beginning on February 4, 1987."],[0,"(d) Approval or disapproval of reports and management programs"],[0,"(1) Deadline"],[1,"Subject to paragraph (2), not later than 180 days after the date of submission to the Administrator of any report or management program under this section (other than subsections (h), (i), and (k)), the Administrator shall either approve or disapprove such report or management program, as the case may be. The Administrator may approve a portion of a management program under this subsection. If the Administrator does not disapprove a report, management program, or portion of a management program in such 180-day period, such report, management program, or portion shall be deemed approved for purposes of this section."],[0,"(2) Procedure for disapproval"],[1,"If, after notice and opportunity for public comment and consultation with appropriate Federal and State agencies and other interested persons, the Administrator determines that—"],[2,"(A) the proposed management program or any portion thereof does not meet the requirements of subsection (b)(2) of this section or is not likely to satisfy, in whole or in part, the goals and requirements of this chapter;"],[2,"(B) adequate authority does not exist, or adequate resources are not available, to implement such program or portion;"],[2,"(C) the schedule for implementing such program or portion is not sufficiently expeditious; or"],[2,"(D) the practices and measures proposed in such program or portion are not adequate to reduce the level of pollution in navigable waters in the State resulting from nonpoint sources and to improve the quality of navigable waters in the State;"],[1,"the Administrator shall within 6 months of the receipt of the proposed program notify the State of any revisions or modifications necessary to obtain approval. The State shall thereupon have an additional 3 months to submit its revised management program and the Administrator shall approve or disapprove such revised program within three months of receipt."],[0,"(3) Failure of State to submit report"],[1,"If a Governor of a State does not submit the report required by subsection (a) within the period specified by subsection (c)(2), the Administrator shall, within 30 months after February 4, 1987, prepare a report for such State which makes the identifications required by paragraphs (1)(A) and (1)(B) of subsection (a). Upon completion of the requirement of the preceding sentence and after notice and opportunity for comment, the Administrator shall report to Congress on his actions pursuant to this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1329?type=usc&year=mostrecent&link-type=html"},"head":"§1329. Nonpoint source management programs","tname":"Navigation and Navigable Waters","by":{"0":"4, 17, 18, 24, 25, 2, 25, 4, 11, 24, 42, 2, 11","3":"1, 10, 2, 10"}},{"t":"usc","label":"33 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/33/1342","subs":["(a)(1)","(b)","(a)","(b)(1)(D)","(d)","(s)(2)","(s)(3)(B)"],"stext":{"head":"§1342. National pollutant discharge elimination system","paras":[[0,"(a) Permits for discharge of pollutants"],[0,"(1) Except as provided in sections 1328 and 1344 of this title, the Administrator may, after opportunity for public hearing issue a permit for the discharge of any pollutant, or combination of pollutants, notwithstanding section 1311(a) of this title, upon condition that such discharge will meet either (A) all applicable requirements under sections 1311, 1312, 1316, 1317, 1318, and 1343 of this title, or (B) prior to the taking of necessary implementing actions relating to all such requirements, such conditions as the Administrator determines are necessary to carry out the provisions of this chapter."],[0,"(2) The Administrator shall prescribe conditions for such permits to assure compliance with the requirements of paragraph (1) of this subsection, including conditions on data and information collection, reporting, and such other requirements as he deems appropriate."],[0,"(3) The permit program of the Administrator under paragraph (1) of this subsection, and permits issued thereunder, shall be subject to the same terms, conditions, and requirements as apply to a State permit program and permits issued thereunder under subsection (b) of this section."],[0,"(4) All permits for discharges into the navigable waters issued pursuant to section 407 of this title shall be deemed to be permits issued under this subchapter, and permits issued under this subchapter shall be deemed to be permits issued under section 407 of this title, and shall continue in force and effect for their term unless revoked, modified, or suspended in accordance with the provisions of this chapter."],[0,"(5) No permit for a discharge into the navigable waters shall be issued under section 407 of this title after October 18, 1972. Each application for a permit under section 407 of this title, pending on October 18, 1972, shall be deemed to be an application for a permit under this section. The Administrator shall authorize a State, which he determines has the capability of administering a permit program which will carry out the objectives of this chapter to issue permits for discharges into the navigable waters within the jurisdiction of such State. The Administrator may exercise the authority granted him by the preceding sentence only during the period which begins on October 18, 1972, and ends either on the ninetieth day after the date of the first promulgation of guidelines required by section 1314(i)(2) of this title, or the date of approval by the Administrator of a permit program for such State under subsection (b) of this section, whichever date first occurs, and no such authorization to a State shall extend beyond the last day of such period. Each such permit shall be subject to such conditions as the Administrator determines are necessary to carry out the provisions of this chapter. No such permit shall issue if the Administrator objects to such issuance."],[0,"(b) State permit programs"],[0,"At any time after the promulgation of the guidelines required by subsection (i)(2) of section 1314 of this title, the Governor of each State desiring to administer its own permit program for discharges into navigable waters within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State water pollution control agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program. The Administrator shall approve each submitted program unless he determines that adequate authority does not exist:"],[0,"(1) To issue permits which—"],[1,"(A) apply, and insure compliance with, any applicable requirements of sections 1311, 1312, 1316, 1317, and 1343 of this title;"],[1,"(B) are for fixed terms not exceeding five years; and"],[1,"(C) can be terminated or modified for cause including, but not limited to, the following:"],[2,"(i) violation of any condition of the permit;"],[2,"(ii) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[2,"(iii) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge;"],[1,"(D) control the disposal of pollutants into wells;"],[0,"(2)(A) To issue permits which apply, and insure compliance with, all applicable requirements of section 1318 of this title; or"],[0,"(B) To inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title;"],[0,"(3) To insure that the public, and any other State the waters of which may be affected, receive notice of each application for a permit and to provide an opportunity for public hearing before a ruling on each such application;"],[0,"(4) To insure that the Administrator receives notice of each application (including a copy thereof) for a permit;"],[0,"(5) To insure that any State (other than the permitting State), whose waters may be affected by the issuance of a permit may submit written recommendations to the permitting State (and the Administrator) with respect to any permit application and, if any part of such written recommendations are not accepted by the permitting State, that the permitting State will notify such affected State (and the Administrator) in writing of its failure to so accept such recommendations together with its reasons for so doing;"],[0,"(6) To insure that no permit will be issued if, in the judgment of the Secretary of the Army acting through the Chief of Engineers, after consultation with the Secretary of the department in which the Coast Guard is operating, anchorage and navigation of any of the navigable waters would be substantially impaired thereby;"],[0,"(7) To abate violations of the permit or the permit program, including civil and criminal penalties and other ways and means of enforcement;"],[0,"(8) To insure that any permit for a discharge from a publicly owned treatment works includes conditions to require the identification in terms of character and volume of pollutants of any significant source introducing pollutants subject to pretreatment standards under section 1317(b) of this title into such works and a program to assure compliance with such pretreatment standards by each such source, in addition to adequate notice to the permitting agency of (A) new introductions into such works of pollutants from any source which would be a new source as defined in section 1316 of this title if such source were discharging pollutants, (B) new introductions of pollutants into such works from a source which would be subject to section 1311 of this title if it were discharging such pollutants, or (C) a substantial change in volume or character of pollutants being introduced into such works by a source introducing pollutants into such works at the time of issuance of the permit. Such notice shall include information on the quality and quantity of effluent to be introduced into such treatment works and any anticipated impact of such change in the quantity or quality of effluent to be discharged from such publicly owned treatment works; and"],[0,"(9) To insure that any industrial user of any publicly owned treatment works will comply with sections 1284(b), 1317, and 1318 of this title."],[0,"(c) Suspension of Federal program upon submission of State program; withdrawal of approval of State program; return of State program to Administrator"],[0,"(1) Not later than ninety days after the date on which a State has submitted a program (or revision thereof) pursuant to subsection (b) of this section, the Administrator shall suspend the issuance of permits under subsection (a) of this section as to those discharges subject to such program unless he determines that the State permit program does not meet the requirements of subsection (b) of this section or does not conform to the guidelines issued under section 1314(i)(2) of this title. If the Administrator so determines, he shall notify the State of any revisions or modifications necessary to conform to such requirements or guidelines."],[0,"(2) Any State permit program under this section shall at all times be in accordance with this section and guidelines promulgated pursuant to section 1314(i)(2) of this title."],[0,"(3) Whenever the Administrator determines after public hearing that a State is not administering a program approved under this section in accordance with requirements of this section, he shall so notify the State and, if appropriate corrective action is not taken within a reasonable time, not to exceed ninety days, the Administrator shall withdraw approval of such program. The Administrator shall not withdraw approval of any such program unless he shall first have notified the State, and made public, in writing, the reasons for such withdrawal."],[0,"(4) Limitations on partial permit program returns and withdrawals.—A State may return to the Administrator administration, and the Administrator may withdraw under paragraph (3) of this subsection approval, of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1342?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1342. National pollutant discharge elimination system","tname":"Navigation and Navigable Waters","by":{"0":"2, 10, 37","1":"3, 3, 3, 3","3":"14, 20, 20"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","subs":["(a)"],"stext":{"head":"§1344. Permits for dredged or fill material","paras":[[0,"(a) Discharge into navigable waters at specified disposal sites"],[0,"The Secretary may issue permits, after notice and opportunity for public hearings for the discharge of dredged or fill material into the navigable waters at specified disposal sites. Not later than the fifteenth day after the date an applicant submits all the information required to complete an application for a permit under this subsection, the Secretary shall publish the notice required by this subsection."],[0,"(b) Specification for disposal sites"],[0,"Subject to subsection (c) of this section, each such disposal site shall be specified for each such permit by the Secretary (1) through the application of guidelines developed by the Administrator, in conjunction with the Secretary, which guidelines shall be based upon criteria comparable to the criteria applicable to the territorial seas, the contiguous zone, and the ocean under section 1343(c) of this title, and (2) in any case where such guidelines under clause (1) alone would prohibit the specification of a site, through the application additionally of the economic impact of the site on navigation and anchorage."],[0,"(c) Denial or restriction of use of defined areas as disposal sites"],[0,"The Administrator is authorized to prohibit the specification (including the withdrawal of specification) of any defined area as a disposal site, and he is authorized to deny or restrict the use of any defined area for specification (including the withdrawal of specification) as a disposal site, whenever he determines, after notice and opportunity for public hearings, that the discharge of such materials into such area will have an unacceptable adverse effect on municipal water supplies, shellfish beds and fishery areas (including spawning and breeding areas), wildlife, or recreational areas. Before making such determination, the Administrator shall consult with the Secretary. The Administrator shall set forth in writing and make public his findings and his reasons for making any determination under this subsection."],[0,"(d) \"Secretary\" defined"],[0,"The term \"Secretary\" as used in this section means the Secretary of the Army, acting through the Chief of Engineers."],[0,"(e) General permits on State, regional, or nationwide basis"],[0,"(1) In carrying out his functions relating to the discharge of dredged or fill material under this section, the Secretary may, after notice and opportunity for public hearing, issue general permits on a State, regional, or nationwide basis for any category of activities involving discharges of dredged or fill material if the Secretary determines that the activities in such category are similar in nature, will cause only minimal adverse environmental effects when performed separately, and will have only minimal cumulative adverse effect on the environment. Any general permit issued under this subsection shall (A) be based on the guidelines described in subsection (b)(1) of this section, and (B) set forth the requirements and standards which shall apply to any activity authorized by such general permit."],[0,"(2) No general permit issued under this subsection shall be for a period of more than five years after the date of its issuance and such general permit may be revoked or modified by the Secretary if, after opportunity for public hearing, the Secretary determines that the activities authorized by such general permit have an adverse impact on the environment or such activities are more appropriately authorized by individual permits."],[0,"(f) Non-prohibited discharge of dredged or fill material"],[0,"(1) Except as provided in paragraph (2) of this subsection, the discharge of dredged or fill material—"],[1,"(A) from normal farming, silviculture, and ranching activities such as plowing, seeding, cultivating, minor drainage, harvesting for the production of food, fiber, and forest products, or upland soil and water conservation practices;"],[1,"(B) for the purpose of maintenance, including emergency reconstruction of recently damaged parts, of currently serviceable structures such as dikes, dams, levees, groins, riprap, breakwaters, causeways, and bridge abutments or approaches, and transportation structures;"],[1,"(C) for the purpose of construction or maintenance of farm or stock ponds or irrigation ditches, or the maintenance of drainage ditches;"],[1,"(D) for the purpose of construction of temporary sedimentation basins on a construction site which does not include placement of fill material into the navigable waters;"],[1,"(E) for the purpose of construction or maintenance of farm roads or forest roads, or temporary roads for moving mining equipment, where such roads are constructed and maintained, in accordance with best management practices, to assure that flow and circulation patterns and chemical and biological characteristics of the navigable waters are not impaired, that the reach of the navigable waters is not reduced, and that any adverse effect on the aquatic environment will be otherwise minimized;"],[1,"(F) resulting from any activity with respect to which a State has an approved program under section 1288(b)(4) of this title which meets the requirements of subparagraphs (B) and (C) of such section,"],[0,"is not prohibited by or otherwise subject to regulation under this section or section 1311(a) or 1342 of this title (except for effluent standards or prohibitions under section 1317 of this title)."],[0,"(2) Any discharge of dredged or fill material into the navigable waters incidental to any activity having as its purpose bringing an area of the navigable waters into a use to which it was not previously subject, where the flow or circulation of navigable waters may be impaired or the reach of such waters be reduced, shall be required to have a permit under this section."],[0,"(g) State administration"],[0,"(1) The Governor of any State desiring to administer its own individual and general permit program for the discharge of dredged or fill material into the navigable waters (other than those waters which are presently used, or are susceptible to use in their natural condition or by reasonable improvement as a means to transport interstate or foreign commerce shoreward to their ordinary high water mark, including all waters which are subject to the ebb and flow of the tide shoreward to their mean high water mark, or mean higher high water mark on the west coast, including wetlands adjacent thereto) within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program."],[0,"(2) Not later than the tenth day after the date of the receipt of the program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall provide copies of such program and statement to the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service."],[0,"(3) Not later than the ninetieth day after the date of the receipt by the Administrator of the program and statement submitted by any State, under paragraph (1) of this subsection, the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, shall submit any comments with respect to such program and statement to the Administrator in writing."],[0,"(h) Determination of State's authority to issue permits under State program; approval; notification; transfers to State program"],[0,"(1) Not later than the one-hundred-twentieth day after the date of the receipt by the Administrator of a program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall determine, taking into account any comments submitted by the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, pursuant to subsection (g) of this section, whether such State has the following authority with respect to the issuance of permits pursuant to such program:"],[1,"(A) To issue permits which—"],[2,"(i) apply, and assure compliance with, any applicable requirements of this section, including, but not limited to, the guidelines established under subsection (b)(1) of this section, and sections 1317 and 1343 of this title;"],[2,"(ii) are for fixed terms not exceeding five years; and"],[2,"(iii) can be terminated or modified for cause including, but not limited to, the following:"],[3,"(I) violation of any condition of the permit;"],[3,"(II) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[3,"(III) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge."],[1,"(B) To issue permits which apply, and assure compliance with, all applicable requirements of section 1318 of this title, or to inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1344?type=usc&year=mostrecent&link-type=html"},"head":"§1344. Permits for dredged or fill material","tname":"Navigation and Navigable Waters","by":{"0":"37","1":"3"}},{"t":"usc","label":"33 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/33/1362","subs":["(7)","(11)","(12)","(14)","(8)","(9)","(10)","(12)(A)","(12)(B)","(6)(B)"],"stext":{"head":"§1362. Definitions","paras":[[0,"Except as otherwise specifically provided, when used in this chapter:"],[0,"(1) The term \"State water pollution control agency\" means the State agency designated by the Governor having responsibility for enforcing State laws relating to the abatement of pollution."],[0,"(2) The term \"interstate agency\" means an agency of two or more States established by or pursuant to an agreement or compact approved by the Congress, or any other agency of two or more States, having substantial powers or duties pertaining to the control of pollution as determined and approved by the Administrator."],[0,"(3) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and the Trust Territory of the Pacific Islands."],[0,"(4) The term \"municipality\" means a city, town, borough, county, parish, district, association, or other public body created by or pursuant to State law and having jurisdiction over disposal of sewage, industrial wastes, or other wastes, or an Indian tribe or an authorized Indian tribal organization, or a designated and approved management agency under section 1288 of this title."],[0,"(5) The term \"person\" means an individual, corporation, partnership, association, State, municipality, commission, or political subdivision of a State, or any interstate body."],[0,"(6) The term \"pollutant\" means dredged spoil, solid waste, incinerator residue, sewage, garbage, sewage sludge, munitions, chemical wastes, biological materials, radioactive materials, heat, wrecked or discarded equipment, rock, sand, cellar dirt and industrial, municipal, and agricultural waste discharged into water. This term does not mean (A) \"sewage from vessels or a discharge incidental to the normal operation of a vessel of the Armed Forces\" within the meaning of section 1322 of this title; or (B) water, gas, or other material which is injected into a well to facilitate production of oil or gas, or water derived in association with oil or gas production and disposed of in a well, if the well used either to facilitate production or for disposal purposes is approved by authority of the State in which the well is located, and if such State determines that such injection or disposal will not result in the degradation of ground or surface water resources."],[0,"(7) The term \"navigable waters\" means the waters of the United States, including the territorial seas."],[0,"(8) The term \"territorial seas\" means the belt of the seas measured from the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters, and extending seaward a distance of three miles."],[0,"(9) The term \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention of the Territorial Sea and the Contiguous Zone."],[0,"(10) The term \"ocean\" means any portion of the high seas beyond the contiguous zone."],[0,"(11) The term \"effluent limitation\" means any restriction established by a State or the Administrator on quantities, rates, and concentrations of chemical, physical, biological, and other constituents which are discharged from point sources into navigable waters, the waters of the contiguous zone, or the ocean, including schedules of compliance."],[0,"(12) The term \"discharge of a pollutant\" and the term \"discharge of pollutants\" each means (A) any addition of any pollutant to navigable waters from any point source, (B) any addition of any pollutant to the waters of the contiguous zone or the ocean from any point source other than a vessel or other floating craft."],[0,"(13) The term \"toxic pollutant\" means those pollutants, or combinations of pollutants, including disease-causing agents, which after discharge and upon exposure, ingestion, inhalation or assimilation into any organism, either directly from the environment or indirectly by ingestion through food chains, will, on the basis of information available to the Administrator, cause death, disease, behavioral abnormalities, cancer, genetic mutations, physiological malfunctions (including malfunctions in reproduction) or physical deformations, in such organisms or their offspring."],[0,"(14) The term \"point source\" means any discernible, confined and discrete conveyance, including but not limited to any pipe, ditch, channel, tunnel, conduit, well, discrete fissure, container, rolling stock, concentrated animal feeding operation, or vessel or other floating craft, from which pollutants are or may be discharged. This term does not include agricultural stormwater discharges and return flows from irrigated agriculture."],[0,"(15) The term \"biological monitoring\" shall mean the determination of the effects on aquatic life, including accumulation of pollutants in tissue, in receiving waters due to the discharge of pollutants (A) by techniques and procedures, including sampling of organisms representative of appropriate levels of the food chain appropriate to the volume and the physical, chemical, and biological characteristics of the effluent, and (B) at appropriate frequencies and locations."],[0,"(16) The term \"discharge\" when used without qualification includes a discharge of a pollutant, and a discharge of pollutants."],[0,"(17) The term \"schedule of compliance\" means a schedule of remedial measures including an enforceable sequence of actions or operations leading to compliance with an effluent limitation, other limitation, prohibition, or standard."],[0,"(18) The term \"industrial user\" means those industries identified in the Standard Industrial Classification Manual, Bureau of the Budget, 1967, as amended and supplemented, under the category of \"Division D—Manufacturing\" and such other classes of significant waste producers as, by regulation, the Administrator deems appropriate."],[0,"(19) The term \"pollution\" means the man-made or man-induced alteration of the chemical, physical, biological, and radiological integrity of water."],[0,"(20) The term \"medical waste\" means isolation wastes; infectious agents; human blood and blood products; pathological wastes; sharps; body parts; contaminated bedding; surgical wastes and potentially contaminated laboratory wastes; dialysis wastes; and such additional medical items as the Administrator shall prescribe by regulation."],[0,"(21) Coastal recreation waters.—"],[1,"(A) In general.—The term \"coastal recreation waters\" means—"],[2,"(i) the Great Lakes; and"],[2,"(ii) marine coastal waters (including coastal estuaries) that are designated under section 1313(c) of this title by a State for use for swimming, bathing, surfing, or similar water contact activities."],[1,"(B) Exclusions.—The term \"coastal recreation waters\" does not include—"],[2,"(i) inland waters; or"],[2,"(ii) waters upstream of the mouth of a river or stream having an unimpaired natural connection with the open sea."],[0,"(22) Floatable material.—"],[1,"(A) In general.—The term \"floatable material\" means any foreign matter that may float or remain suspended in the water column."],[1,"(B) Inclusions.—The term \"floatable material\" includes—"],[2,"(i) plastic;"],[2,"(ii) aluminum cans;"],[2,"(iii) wood products;"],[2,"(iv) bottles; and"],[2,"(v) paper products."],[0,"(23) Pathogen indicator.—The term \"pathogen indicator\" means a substance that indicates the potential for human infectious disease."],[0,"(24) Oil and gas exploration and production.—The term \"oil and gas exploration, production, processing, or treatment operations or transmission facilities\" means all field activities or operations associated with exploration, production, processing, or treatment operations, or transmission facilities, including activities necessary to prepare a site for drilling and for the movement and placement of drilling equipment, whether or not such field activities or operations may be considered to be construction activities."],[0,"(25) Recreational vessel.—"],[1,"(A) In general.—The term \"recreational vessel\" means any vessel that is—"],[2,"(i) manufactured or used primarily for pleasure; or"],[2,"(ii) leased, rented, or chartered to a person for the pleasure of that person."],[1,"(B) Exclusion.—The term \"recreational vessel\" does not include a vessel that is subject to Coast Guard inspection and that—"],[2,"(i) is engaged in commercial use; or"],[2,"(ii) carries paying passengers."],[0,"(26) Treatment works.—The term \"treatment works\" has the meaning given the term in section 1292 of this title."],[0,"(27) Green infrastructure.—The term \"green infrastructure\" means the range of measures that use plant or soil systems, permeable pavement or other permeable surfaces or substrates, stormwater harvest and reuse, or landscaping to store, infiltrate, or evapotranspirate stormwater and reduce flows to sewer systems or to surface waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1362?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1362. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"2, 10, 37, passim, passim","1":"9, 13, 9, 13, 9, 13, 9, 13, 9, 13, 9, 13, 9, 13, 9, 13, 9, 13, 2","3":"14, passim, 4, 5, 22, 23"}},{"t":"usc","label":"33 U.S.C. § 1371","url":"https://www.law.cornell.edu/uscode/text/33/1371","subs":["(b)"],"by":{"0":"37"}},{"t":"usc","label":"42 U.S.C. § 300f","url":"https://www.law.cornell.edu/uscode/text/42/300f","stext":{"head":"§300f. Definitions","paras":[[0,"For purposes of this subchapter:"],[1,"(1) The term \"primary drinking water regulation\" means a regulation which—"],[2,"(A) applies to public water systems;"],[2,"(B) specifies contaminants which, in the judgment of the Administrator, may have any adverse effect on the health of persons;"],[2,"(C) specifies for each such contaminant either—"],[3,"(i) a maximum contaminant level, if, in the judgment of the Administrator, it is economically and technologically feasible to ascertain the level of such contaminant in water in public water systems, or"],[3,"(ii) if, in the judgment of the Administrator, it is not economically or technologically feasible to so ascertain the level of such contaminant, each treatment technique known to the Administrator which leads to a reduction in the level of such contaminant sufficient to satisfy the requirements of section 300g–1 of this title; and"],[2,"(D) contains criteria and procedures to assure a supply of drinking water which dependably complies with such maximum contaminant levels; including accepted methods for quality control and testing procedures to insure compliance with such levels and to insure proper operation and maintenance of the system, and requirements as to (i) the minimum quality of water which may be taken into the system and (ii) siting for new facilities for public water systems."],[1,"At any time after promulgation of a regulation referred to in this paragraph, the Administrator may add equally effective quality control and testing procedures by guidance published in the Federal Register. Such procedures shall be treated as an alternative for public water systems to the quality control and testing procedures listed in the regulation."],[1,"(2) The term \"secondary drinking water regulation\" means a regulation which applies to public water systems and which specifies the maximum contaminant levels which, in the judgment of the Administrator, are requisite to protect the public welfare. Such regulations may apply to any contaminant in drinking water (A) which may adversely affect the odor or appearance of such water and consequently may cause a substantial number of the persons served by the public water system providing such water to discontinue its use, or (B) which may otherwise adversely affect the public welfare. Such regulations may vary according to geographic and other circumstances."],[1,"(3) The term \"maximum contaminant level\" means the maximum permissible level of a contaminant in water which is delivered to any user of a public water system."],[1,"(4) Public water system.—"],[2,"(A) In general.—The term \"public water system\" means a system for the provision to the public of water for human consumption through pipes or other constructed conveyances, if such system has at least fifteen service connections or regularly serves at least twenty-five individuals. Such term includes (i) any collection, treatment, storage, and distribution facilities under control of the operator of such system and used primarily in connection with such system, and (ii) any collection or pretreatment storage facilities not under such control which are used primarily in connection with such system."],[2,"(B) Connections.—"],[3,"(i) In general.—For purposes of subparagraph (A), a connection to a system that delivers water by a constructed conveyance other than a pipe shall not be considered a connection, if—"],[4,"(I) the water is used exclusively for purposes other than residential uses (consisting of drinking, bathing, and cooking, or other similar uses);"],[4,"(II) the Administrator or the State (in the case of a State exercising primary enforcement responsibility for public water systems) determines that alternative water to achieve the equivalent level of public health protection provided by the applicable national primary drinking water regulation is provided for residential or similar uses for drinking and cooking; or"],[4,"(III) the Administrator or the State (in the case of a State exercising primary enforcement responsibility for public water systems) determines that the water provided for residential or similar uses for drinking, cooking, and bathing is centrally treated or treated at the point of entry by the provider, a pass-through entity, or the user to achieve the equivalent level of protection provided by the applicable national primary drinking water regulations."],[3,"(ii) Irrigation districts.—An irrigation district in existence prior to May 18, 1994, that provides primarily agricultural service through a piped water system with only incidental residential or similar use shall not be considered to be a public water system if the system or the residential or similar users of the system comply with subclause (II) or (III) of clause (i)."],[2,"(C) Transition period.—A water supplier that would be a public water system only as a result of modifications made to this paragraph by the Safe Drinking Water Act Amendments of 1996 shall not be considered a public water system for purposes of the Act until the date that is two years after August 6, 1996. If a water supplier does not serve 15 service connections (as defined in subparagraphs (A) and (B)) or 25 people at any time after the conclusion of the 2-year period, the water supplier shall not be considered a public water system."],[1,"(5) The term \"supplier of water\" means any person who owns or operates a public water system."],[1,"(6) The term \"contaminant\" means any physical, chemical, biological, or radiological substance or matter in water."],[1,"(7) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[1,"(8) The term \"Agency\" means the Environmental Protection Agency."],[1,"(9) The term \"Council\" means the National Drinking Water Advisory Council established under section 300j–5 of this title."],[1,"(10) The term \"municipality\" means a city, town, or other public body created by or pursuant to State law, or an Indian Tribe."],[1,"(11) The term \"Federal agency\" means any department, agency, or instrumentality of the United States."],[1,"(12) The term \"person\" means an individual, corporation, company, association, partnership, State, municipality, or Federal agency (and includes officers, employees, and agents of any corporation, company, association, State, municipality, or Federal agency)."],[1,"(13)(A) Except as provided in subparagraph (B), the term \"State\" includes, in addition to the several States, only the District of Columbia, Guam, the Commonwealth of Puerto Rico, the Northern Mariana Islands, the Virgin Islands, American Samoa, and the Trust Territory of the Pacific Islands."],[1,"(B) For purposes of section 300j–12 of this title, the term \"State\" means each of the 50 States, the District of Columbia, and the Commonwealth of Puerto Rico."],[1,"(14) The term \"Indian Tribe\" means any Indian tribe having a Federally recognized governing body carrying out substantial governmental duties and powers over any area. For purposes of sections 300j–12, 300j–19a, and 300j–19b of this title, the term includes any Native village (as defined in section 1602(c) of title 43)."],[1,"(15) Community water system.—The term \"community water system\" means a public water system that—"],[2,"(A) serves at least 15 service connections used by year-round residents of the area served by the system; or"],[2,"(B) regularly serves at least 25 year-round residents."],[1,"(16) Noncommunity water system.—The term \"noncommunity water system\" means a public water system that is not a community water system."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300f?type=usc&year=mostrecent&link-type=html"},"head":"§300f. Definitions","tname":"The Public Health and Welfare","by":{"0":"8","1":"4, 31"}},{"t":"usc","label":"42 U.S.C. § 300h","url":"https://www.law.cornell.edu/uscode/text/42/300h","subs":["(b)"],"stext":{"head":"§300h. Regulations for State programs","paras":[[0,"(a) Publication of proposed regulations; promulgation; amendments; public hearings; administrative consultations"],[0,"(1) The Administrator shall publish proposed regulations for State underground injection control programs within 180 days after December 16, 1974. Within 180 days after publication of such proposed regulations, he shall promulgate such regulations with such modifications as he deems appropriate. Any regulation under this subsection may be amended from time to time."],[0,"(2) Any regulation under this section shall be proposed and promulgated in accordance with section 553 of title 5 (relating to rulemaking), except that the Administrator shall provide opportunity for public hearing prior to promulgation of such regulations. In proposing and promulgating regulations under this section the Administrator shall consult with the Secretary, the National Drinking Water Advisory Council, and other appropriate Federal entities and with interested State entities."],[0,"(b) Minimum requirements; restrictions"],[0,"(1) Regulations under subsection (a) for State underground injection programs shall contain minimum requirements for effective programs to prevent underground injection which endangers drinking water sources within the meaning of subsection (d)(2). Such regulations shall require that a State program, in order to be approved under section 300h–1 of this title—"],[1,"(A) shall prohibit, effective on the date on which the applicable underground injection control program takes effect, any underground injection in such State which is not authorized by a permit issued by the State (except that the regulations may permit a State to authorize underground injection by rule);"],[1,"(B) shall require (i) in the case of a program which provides for authorization of underground injection by permit, that the applicant for the permit to inject must satisfy the State that the underground injection will not endanger drinking water sources, and (ii) in the case of a program which provides for such an authorization by rule, that no rule may be promulgated which authorizes any underground injection which endangers drinking water sources;"],[1,"(C) shall include inspection, monitoring, recordkeeping, and reporting requirements; and"],[1,"(D) shall apply (i) as prescribed by section 300j–6(b) 1 of this title, to underground injections by Federal agencies, and (ii) to underground injections by any other person whether or not occurring on property owned or leased by the United States."],[0,"(2) Regulations of the Administrator under this section for State underground injection control programs may not prescribe requirements which interfere with or impede—"],[1,"(A) the underground injection of brine or other fluids which are brought to the surface in connection with oil or natural gas production or natural gas storage operations, or"],[1,"(B) any underground injection for the secondary or tertiary recovery of oil or natural gas,"],[0,"unless such requirements are essential to assure that underground sources of drinking water will not be endangered by such injection."],[0,"(3)(A) The regulations of the Administrator under this section shall permit or provide for consideration of varying geologic, hydrological, or historical conditions in different States and in different areas within a State."],[0,"(B)(i) In prescribing regulations under this section the Administrator shall, to the extent feasible, avoid promulgation of requirements which would unnecessarily disrupt State underground injection control programs which are in effect and being enforced in a substantial number of States."],[0,"(ii) For the purpose of this subparagraph, a regulation prescribed by the Administrator under this section shall be deemed to disrupt a State underground injection control program only if it would be infeasible to comply with both such regulation and the State underground injection control program."],[0,"(iii) For the purpose of this subparagraph, a regulation prescribed by the Administrator under this section shall be deemed unnecessary only if, without such regulation, underground sources of drinking water will not be endangered by an underground injection."],[0,"(C) Nothing in this section shall be construed to alter or affect the duty to assure that underground sources of drinking water will not be endangered by any underground injection."],[0,"(c) Temporary permits; notice and hearing"],[0,"(1) The Administrator may, upon application of the Governor of a State which authorizes underground injection by means of permits, authorize such State to issue (without regard to subsection (b)(1)(B)(i)) temporary permits for underground injection which may be effective until the, expiration of four years after December 16, 1974, if—"],[1,"(A) the Administrator finds that the State has demonstrated that it is unable and could not reasonably have been able to process all permit applications within the time available;"],[1,"(B) the Administrator determines the adverse effect on the environment of such temporary permits is not unwarranted;"],[1,"(C) such temporary permits will be issued only with respect to injection wells in operation on the date on which such State's permit program approved under this part first takes effect and for which there was inadequate time to process its permit application; and"],[1,"(D) the Administrator determines the temporary permits require the use of adequate safeguards established by rules adopted by him."],[0,"(2) The Administrator may, upon application of the Governor of a State which authorizes underground injection by means of permits, authorize such State to issue (without regard to subsection (b)(1)(B)(i)), but after reasonable notice and hearing, one or more temporary permits each of which is applicable to a particular injection well and to the underground injection of a particular fluid and which may be effective until the expiration of four years after December 16, 1974, if the State finds, on the record of such hearing—"],[1,"(A) that technology (or other means) to permit safe injection of the fluid in accordance with the applicable underground injection control program is not generally available (taking costs into consideration);"],[1,"(B) that injection of the fluid would be less harmful to health than the use of other available means of disposing of waste or producing the desired product; and"],[1,"(C) that available technology or other means have been employed (and will be employed) to reduce the volume and toxicity of the fluid and to minimize the potentially adverse effect of the injection on the public health."],[0,"(d) \"Underground injection\" defined; underground injection endangerment of drinking water sources"],[0,"For purposes of this part:"],[1,"(1) Underground injection.—The term \"underground injection\"—"],[2,"(A) means the subsurface emplacement of fluids by well injection; and"],[2,"(B) excludes—"],[3,"(i) the underground injection of natural gas for purposes of storage; and"],[3,"(ii) the underground injection of fluids or propping agents (other than diesel fuels) pursuant to hydraulic fracturing operations related to oil, gas, or geothermal production activities."],[1,"(2) Underground injection endangers drinking water sources if such injection may result in the presence in underground water which supplies or can reasonably be expected to supply any public water system of any contaminant, and if the presence of such contaminant may result in such system's not complying with any national primary drinking water regulation or may otherwise adversely affect the health of persons."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300h?type=usc&year=mostrecent&link-type=html"},"head":"§300h. Regulations for State programs","tname":"The Public Health and Welfare","by":{"0":"8, 43","1":"31, 31"}},{"t":"usc","label":"42 U.S.C. § 300h-1","url":"https://www.law.cornell.edu/uscode/text/42/300h-1","subs":["(c)"],"by":{"0":"11"}},{"t":"usc","label":"42 U.S.C. § 6903","url":"https://www.law.cornell.edu/uscode/text/42/6903","subs":["(3)"],"stext":{"head":"§6903. Definitions","paras":[[0,"As used in this chapter:"],[0,"(1) The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[0,"(2) The term \"construction,\" with respect to any project of construction under this chapter, means (A) the erection or building of new structures and acquisition of lands or interests therein, or the acquisition, replacement, expansion, remodeling, alteration, modernization, or extension of existing structures, and (B) the acquisition and installation of initial equipment of, or required in connection with, new or newly acquired structures or the expanded, remodeled, altered, modernized or extended part of existing structures (including trucks and other motor vehicles, and tractors, cranes, and other machinery) necessary for the proper utilization and operation of the facility after completion of the project; and includes preliminary planning to determine the economic and engineering feasibility and the public health and safety aspects of the project, the engineering, architectural, legal, fiscal, and economic investigations and studies, and any surveys, designs, plans, working drawings, specifications, and other action necessary for the carrying out of the project, and (C) the inspection and supervision of the process of carrying out the project to completion."],[0,"(2A) The term \"demonstration\" means the initial exhibition of a new technology process or practice or a significantly new combination or use of technologies, processes or practices, subsequent to the development stage, for the purpose of proving technological feasibility and cost effectiveness."],[0,"(3) The term \"disposal\" means the discharge, deposit, injection, dumping, spilling, leaking, or placing of any solid waste or hazardous waste into or on any land or water so that such solid waste or hazardous waste or any constituent thereof may enter the environment or be emitted into the air or discharged into any waters, including ground waters."],[0,"(4) The term \"Federal agency\" means any department, agency, or other instrumentality of the Federal Government, any independent agency or establishment of the Federal Government including any Government corporation, and the Government Publishing Office."],[0,"(5) The term \"hazardous waste\" means a solid waste, or combination of solid wastes, which because of its quantity, concentration, or physical, chemical, or infectious characteristics may—"],[1,"(A) cause, or significantly contribute to an increase in mortality or an increase in serious irreversible, or incapacitating reversible, illness; or"],[1,"(B) pose a substantial present or potential hazard to human health or the environment when improperly treated, stored, transported, or disposed of, or otherwise managed."],[0,"(6) The term \"hazardous waste generation\" means the act or process of producing hazardous waste."],[0,"(7) The term \"hazardous waste management\" means the systematic control of the collection, source separation, storage, transportation, processing, treatment, recovery, and disposal of hazardous wastes."],[0,"(8) For purposes of Federal financial assistance (other than rural communities assistance), the term \"implementation\" does not include the acquisition, leasing, construction, or modification of facilities or equipment or the acquisition, leasing, or improvement of land."],[0,"(9) The term \"intermunicipal agency\" means an agency established by two or more municipalities with responsibility for planning or administration of solid waste."],[0,"(10) The term \"interstate agency\" means an agency of two or more municipalities in different States, or an agency established by two or more States, with authority to provide for the management of solid wastes and serving two or more municipalities located in different States."],[0,"(11) The term \"long-term contract\" means, when used in relation to solid waste supply, a contract of sufficient duration to assure the viability of a resource recovery facility (to the extent that such viability depends upon solid waste supply)."],[0,"(12) The term \"manifest\" means the form used for identifying the quantity, composition, and the origin, routing, and destination of hazardous waste during its transportation from the point of generation to the point of disposal, treatment, or storage."],[0,"(13) The term \"municipality\" (A) means a city, town, borough, county, parish, district, or other public body created by or pursuant to State law, with responsibility for the planning or administration of solid waste management, or an Indian tribe or authorized tribal organization or Alaska Native village or organization, and (B) includes any rural community or unincorporated town or village or any other public entity for which an application for assistance is made by a State or political subdivision thereof."],[0,"(14) The term \"open dump\" means any facility or site where solid waste is disposed of which is not a sanitary landfill which meets the criteria promulgated under section 6944 of this title and which is not a facility for disposal of hazardous waste."],[0,"(15) The term \"person\" means an individual, trust, firm, joint stock company, corporation (including a government corporation), partnership, association, State, municipality, commission, political subdivision of a State, or any interstate body and shall include each department, agency, and instrumentality of the United States."],[0,"(16) The term \"procurement item\" means any device, good, substance, material, product, or other item whether real or personal property which is the subject of any purchase, barter, or other exchange made to procure such item."],[0,"(17) The term \"procuring agency\" means any Federal agency, or any State agency or agency of a political subdivision of a State which is using appropriated Federal funds for such procurement, or any person contracting with any such agency with respect to work performed under such contract."],[0,"(18) The term \"recoverable\" refers to the capability and likelihood of being recovered from solid waste for a commercial or industrial use."],[0,"(19) The term \"recovered material\" means waste material and byproducts which have been recovered or diverted from solid waste, but such term does not include those materials and byproducts generated from, and commonly reused within, an original manufacturing process."],[0,"(20) The term \"recovered resources\" means material or energy recovered from solid waste."],[0,"(21) The term \"resource conservation\" means reduction of the amounts of solid waste that are generated, reduction of overall resource consumption, and utilization of recovered resources."],[0,"(22) The term \"resource recovery\" means the recovery of material or energy from solid waste."],[0,"(23) The term \"resource recovery system\" means a solid waste management system which provides for collection, separation, recycling, and recovery of solid wastes, including disposal of nonrecoverable waste residues."],[0,"(24) The term \"resource recovery facility\" means any facility at which solid waste is processed for the purpose of extracting, converting to energy, or otherwise separating and preparing solid waste for reuse."],[0,"(25) The term \"regional authority\" means the authority established or designated under section 6946 of this title."],[0,"(26) The term \"sanitary landfill\" means a facility for the disposal of solid waste which meets the criteria published under section 6944 of this title."],[0,"(26A) The term \"sludge\" means any solid, semisolid or liquid waste generated from a municipal, commercial, or industrial wastewater treatment plant, water supply treatment plant, or air pollution control facility or any other such waste having similar characteristics and effects."],[0,"(27) The term \"solid waste\" means any garbage, refuse, sludge from a waste treatment plant, water supply treatment plant, or air pollution control facility and other discarded material, including solid, liquid, semisolid, or contained gaseous material resulting from industrial, commercial, mining, and agricultural operations, and from community activities, but does not include solid or dissolved material in domestic sewage, or solid or dissolved materials in irrigation return flows or industrial discharges which are point sources subject to permits under section 1342 of title 33, or source, special nuclear, or byproduct material as defined by the Atomic Energy Act of 1954, as amended (68 Stat. 923) [42 U.S.C. 2011 et seq.]."],[0,"(28) The term \"solid waste management\" means the systematic administration of activities which provide for the collection, source separation, storage, transportation, transfer, processing, treatment, and disposal of solid waste."],[0,"(29) The term \"solid waste management facility\" includes—"],[1,"(A) any resource recovery system or component thereof,"],[1,"(B) any system, program, or facility for resource conservation, and"],[1,"(C) any facility for the collection, source separation, storage, transportation, transfer, processing, treatment or disposal of solid wastes, including hazardous wastes, whether such facility is associated with facilities generating such wastes or otherwise."],[0,"(30) The terms \"solid waste planning\", \"solid waste management\", and \"comprehensive planning\" include planning or management respecting resource recovery and resource conservation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/6903?type=usc&year=mostrecent&link-type=html"},"head":"§6903. Definitions","tname":"The Public Health and Welfare","by":{"0":"44","1":"32"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(8)"],"stext":{"head":"§9601. Definitions","paras":[[0,"For purpose of this subchapter—"],[1,"(1) The term \"act of God\" means an unanticipated grave natural disaster or other natural phenomenon of an exceptional, inevitable, and irresistible character, the effects of which could not have been prevented or avoided by the exercise of due care or foresight."],[1,"(2) The term \"Administrator\" means the Administrator of the United States Environmental Protection Agency."],[1,"(3) The term \"barrel\" means forty-two United States gallons at sixty degrees Fahrenheit."],[1,"(4) The term \"claim\" means a demand in writing for a sum certain."],[1,"(5) The term \"claimant\" means any person who presents a claim for compensation under this chapter."],[1,"(6) The term \"damages\" means damages for injury or loss of natural resources as set forth in section 9607(a) or 9611(b) of this title."],[1,"(7) The term \"drinking water supply\" means any raw or finished water source that is or may be used by a public water system (as defined in the Safe Drinking Water Act [42 U.S.C. 300f et seq.]) or as drinking water by one or more individuals."],[1,"(8) The term \"environment\" means (A) the navigable waters, the waters of the contiguous zone, and the ocean waters of which the natural resources are under the exclusive management authority of the United States under the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.], and (B) any other surface water, ground water, drinking water supply, land surface or subsurface strata, or ambient air within the United States or under the jurisdiction of the United States."],[1,"(9) The term \"facility\" means (A) any building, structure, installation, equipment, pipe or pipeline (including any pipe into a sewer or publicly owned treatment works), well, pit, pond, lagoon, impoundment, ditch, landfill, storage container, motor vehicle, rolling stock, or aircraft, or (B) any site or area where a hazardous substance has been deposited, stored, disposed of, or placed, or otherwise come to be located; but does not include any consumer product in consumer use or any vessel."],[1,"(10) The term \"federally permitted release\" means (A) discharges in compliance with a permit under section 402 of the Federal Water Pollution Control Act [33 U.S.C. 1342], (B) discharges resulting from circumstances identified and reviewed and made part of the public record with respect to a permit issued or modified under section 402 of the Federal Water Pollution Control Act and subject to a condition of such permit, (C) continuous or anticipated intermittent discharges from a point source, identified in a permit or permit application under section 402 of the Federal Water Pollution Control Act, which are caused by events occurring within the scope of relevant operating or treatment systems, (D) discharges in compliance with a legally enforceable permit under section 404 of the Federal Water Pollution Control Act [33 U.S.C. 1344], (E) releases in compliance with a legally enforceable final permit issued pursuant to section 3005(a) through (d) of the Solid Waste Disposal Act [42 U.S.C. 6925(a)–(d)] from a hazardous waste treatment, storage, or disposal facility when such permit specifically identifies the hazardous substances and makes such substances subject to a standard of practice, control procedure or bioassay limitation or condition, or other control on the hazardous substances in such releases, (F) any release in compliance with a legally enforceable permit issued under section 1412 of title 33 of 1 section 1413 of title 33, (G) any injection of fluids authorized under Federal underground injection control programs or State programs submitted for Federal approval (and not disapproved by the Administrator of the Environmental Protection Agency) pursuant to part C of the Safe Drinking Water Act [42 U.S.C. 300h et seq.], (H) any emission into the air subject to a permit or control regulation under section 111 [42 U.S.C. 7411], section 112 [42 U.S.C. 7412], title I part C [42 U.S.C. 7470 et seq.], title I part D [42 U.S.C. 7501 et seq.], or State implementation plans submitted in accordance with section 110 of the Clean Air Act [42 U.S.C. 7410] (and not disapproved by the Administrator of the Environmental Protection Agency), including any schedule or waiver granted, promulgated, or approved under these sections, (I) any injection of fluids or other materials authorized under applicable State law (i) for the purpose of stimulating or treating wells for the production of crude oil, natural gas, or water, (ii) for the purpose of secondary, tertiary, or other enhanced recovery of crude oil or natural gas, or (iii) which are brought to the surface in conjunction with the production of crude oil or natural gas and which are reinjected, (J) the introduction of any pollutant into a publicly owned treatment works when such pollutant is specified in and in compliance with applicable pretreatment standards of section 307(b) or (c) of the Clean Water Act [33 U.S.C. 1317(b), (c)] and enforceable requirements in a pretreatment program submitted by a State or municipality for Federal approval under section 402 of such Act [33 U.S.C. 1342], and (K) any release of source, special nuclear, or byproduct material, as those terms are defined in the Atomic Energy Act of 1954 [42 U.S.C. 2011 et seq.], in compliance with a legally enforceable license, permit, regulation, or order issued pursuant to the Atomic Energy Act of 1954."],[1,"(11) The term \"Fund\" or \"Trust Fund\" means the Hazardous Substance Superfund established by section 9507 of title 26."],[1,"(12) The term \"ground water\" means water in a saturated zone or stratum beneath the surface of land or water."],[1,"(13) The term \"guarantor\" means any person, other than the owner or operator, who provides evidence of financial responsibility for an owner or operator under this chapter."],[1,"(14) The term \"hazardous substance\" means (A) any substance designated pursuant to section 311(b)(2)(A) of the Federal Water Pollution Control Act [33 U.S.C. 1321(b)(2)(A)], (B) any element, compound, mixture, solution, or substance designated pursuant to section 9602 of this title, (C) any hazardous waste having the characteristics identified under or listed pursuant to section 3001 of the Solid Waste Disposal Act [42 U.S.C. 6921] (but not including any waste the regulation of which under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] has been suspended by Act of Congress), (D) any toxic pollutant listed under section 307(a) of the Federal Water Pollution Control Act [33 U.S.C. 1317(a)], (E) any hazardous air pollutant listed under section 112 of the Clean Air Act [42 U.S.C. 7412], and (F) any imminently hazardous chemical substance or mixture with respect to which the Administrator has taken action pursuant to section 7 of the Toxic Substances Control Act [15 U.S.C. 2606]. The term does not include petroleum, including crude oil or any fraction thereof which is not otherwise specifically listed or designated as a hazardous substance under subparagraphs (A) through (F) of this paragraph, and the term does not include natural gas, natural gas liquids, liquefied natural gas, or synthetic gas usable for fuel (or mixtures of natural gas and such synthetic gas)."],[1,"(15) The term \"navigable waters\" or \"navigable waters of the United States\" means the waters of the United States, including the territorial seas."],[1,"(16) The term \"natural resources\" means land, fish, wildlife, biota, air, water, ground water, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States (including the resources of the fishery conservation zone established by the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.]), any State or local government, any foreign government, any Indian tribe, or, if such resources are subject to a trust restriction on alienation, any member of an Indian tribe."],[1,"(17) The term \"offshore facility\" means any facility of any kind located in, on, or under, any of the navigable waters of the United States, and any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel."],[1,"(18) The term \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land or nonnavigable waters within the United States."],[1,"(19) The term \"otherwise subject to the jurisdiction of the United States\" means subject to the jurisdiction of the United States by virtue of United States citizenship, United States vessel documentation or numbering, or as provided by international agreement to which the United States is a party."],[1,"(20)(A) The term \"owner or operator\" means (i) in the case of a vessel, any person owning, operating, or chartering by demise, such vessel, (ii) in the case of an onshore facility or an offshore facility, any person owning or operating such facility, and (iii) in the case of any facility, title or control of which was conveyed due to bankruptcy, foreclosure, tax delinquency, abandonment, or similar means to a unit of State or local government, any person who owned, operated, or otherwise controlled activities at such facility immediately beforehand. Such term does not include a person, who, without participating in the management of a vessel or facility, holds indicia of ownership primarily to protect his security interest in the vessel or facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9601?type=usc&year=mostrecent&link-type=html"},"head":"§9601. Definitions","tname":"The Public Health and Welfare","by":{"0":"44","1":"32, 32"}},{"t":"law","label":"Pub. L. No. 80-845","by":{"0":"21"}},{"t":"reg","label":"40 C.F.R. § 19.4","url":"https://www.ecfr.gov/current/title-40/section-19.4","by":{"0":"37"}},{"t":"reg","label":"40 C.F.R. § 122.2","url":"https://www.ecfr.gov/current/title-40/section-122.2","by":{"0":"3, 10"}},{"t":"reg","label":"40 C.F.R. § 130.2","url":"https://www.ecfr.gov/current/title-40/section-130.2","subs":["(g)","(h)"],"by":{"0":"26, 26"}},{"t":"reg","label":"40 C.F.R. pt. 144","url":"https://www.ecfr.gov/current/title-40/part-144","by":{"0":"8"}},{"t":"reg","label":"40 C.F.R. § 144.81","url":"https://www.ecfr.gov/current/title-40/section-144.81","by":{"0":"8, 9"}},{"t":"reg","label":"40 C.F.R. § 257.90","url":"https://www.ecfr.gov/current/title-40/section-257.90","by":{"0":"44"}},{"t":"reg","label":"Federal Register:, 39 Fed. Reg. 43,759","url":"https://www.govinfo.gov/link/fr/39/43759","by":{"0":"10"}},{"t":"reg","label":"83 Fed. Reg. 7126","url":"https://www.govinfo.gov/link/fr/83/7126","by":{"0":"16","1":"6"}},{"t":"reg","label":"84 Fed. Reg. 2056","url":"https://www.govinfo.gov/link/fr/84/2056","by":{"0":"37, 38"}},{"t":"reg","label":"84 Fed. Reg. 4154","url":"https://www.govinfo.gov/link/fr/84/4154","by":{"0":"10"}},{"t":"reg","label":"84 Fed. Reg. 16,810","url":"https://www.govinfo.gov/link/fr/84/16810","by":{"0":"passim","1":"passim","3":"23"}},{"t":"case","label":"Complaint, Village of Oconomowoc Lake v. Dayton-Hudson Corp.","cite":"1993 WL 668975","y":1993,"court":"E.D. Wis. Sept. 24","by":{"0":"50"}},{"t":"case","label":"CSX Transp., Inc. v. McBride","cite":"564 U.S. 685","y":2011,"id":"2010/10-235","sc":1,"op":1,"sum":"The Supreme Court affirmed the lower court order in an opinion by Justice Ruth Bader Ginsburg. \"The charge proper in FELA cases, we hold, simply tracks the language Congress employed, informing juries that a defendant railroad caused or contributed to a plaintiff employee's injury if the railroad's negligence played any part in bringing about the injury,\" Ginsburg wrote for the majority.","sumSrc":"Oyez","by":{"1":"23","2":"20"}},{"t":"case","label":"Holmes v. Securities Investor Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Meghrig v. KFC W., Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Tennessee Clean Water Network v. Tennessee Valley Auth.","cite":"905 F.3d 436","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/436/","by":{"1":"23"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14","2":"3"}},{"t":"usc","label":"33 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/33/1365","subs":["(a)(1)"],"by":{"1":"3, 3"}},{"t":"usc","label":"33 U.S.C. § 1370","url":"https://www.law.cornell.edu/uscode/text/33/1370","subs":["(1)","(2)"],"by":{"1":"30, 30"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","subs":["(a)(1)"],"by":{"1":"32"}},{"t":"usc","label":"42 U.S.C. § 9621","url":"https://www.law.cornell.edu/uscode/text/42/9621","subs":["(d)(2)(A)"],"by":{"1":"32"}},{"t":"usc","label":"33 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/33/2701","subs":["(20)"],"by":{"1":"33, 33"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 6902","url":"https://www.law.cornell.edu/uscode/text/42/6902","subs":["(b)"],"by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 6924","url":"https://www.law.cornell.edu/uscode/text/42/6924","subs":["(o)","(p)"],"by":{"1":"32, 32"}},{"t":"usc","label":"42 U.S.C. § 6991b","url":"https://www.law.cornell.edu/uscode/text/42/6991b","subs":["(c)"],"by":{"1":"32"}},{"t":"case","label":"Alabama v. North Carolina","cite":"560 U.S. 330","y":2010,"id":"2009/132-orig","sc":1,"sum":"The Court held that Alabama did not have the power to impose monetary sanctions against North Carolina for violating a multi-state waste cleanup compact.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Ali v. Fed. Bur. of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Am. Wildlands v. Browner","cite":"260 F.3d 1192","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/260/1192/","by":{"2":"37"}},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"sum":"Held.: The Buy Indian Act, which permits the Secretary of the Interior to purchase \"the products of Indian industry... in open market,\" does not authorize the Department of the Interior's Bureau of Indian Affairs (BIA) to enter into road construction contracts with Indianowned companies without first advertising for bids pursuant to Title III of the Federal Property and Administrative Services Act of 1949 (FPASA). …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Asgrow Seed Co. v. Winterboer","cite":"513 U.S. 179","y":1995,"id":"1994/92-2038","sc":1,"sum":"The Court held that a farmer may sell for reproductive purposes only such seed as he has saved for the purpose of replanting his own fields. While the statute allows farmers to save seed to replant and then sell that saved seed to other farmers for planting, the statute prohibits growing protected seed as a \"step in marketing\" it as seed for planting.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"45"}},{"t":"case","label":"Badaracco v. Comm’r of Internal Rev.","cite":"464 U.S. 386","y":1984,"id":"1983/82-1453","sc":1,"sum":"Where a taxpayer fies a false or fraudulent return but later fies a nonfraudulent amended return, § 6501(c)(1) applies and a tax may be assessed \"at any time,\" regardless of whether more than three years have expired since the filing of the amended return. Pp. 391-401. States, also on certiorari to the same court. BADARACCO v. COMMISSIONER (a) The plain and unambiguous language of §6501(c)(1) permits the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"sum":"Chief Justice William H. Rehnquist wrote that the \"substantial and injurious effect\" test was preferable to the \"beyond a reasonable doubt\" test in requests for habeas corpus relief. Habeas proceedings are not to be the primary avenue for resolving disputes; Rehnquist called the writ \"an extraordinary remedy\", reserved for the victims of grave injustice.","sumSrc":"Oyez","by":{"2":"31, 32"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":3,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Citizens Bank of Md. v. Strumpf","cite":"516 U.S. 16","y":1995,"id":"1995/94-1340","sc":1,"sum":"When respondent filed for relief under the Bankruptcy Code, he had a checking account with, and was in default on the remaining balance of a loan from, petitioner bank. Under the Code, a bankruptcy filing gives rise to an automatic stay of a creditor's \"setoff of any debt owing to the debtor that arose before the commencement of the [bankruptcy case] against any claim against the debtor.\" 11 U. S. C. §362(a)(7). …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"57"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Consumer Prod. Safety Comm’n v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Estate of Cowart v. Nicklos Drilling Co.","cite":"505 U.S. 469","y":1992,"id":"1991/91-17","sc":1,"sum":"Section 33(g)'s forfeiture provision applies to a worker whose employer, at the time the worker settles with a third party, is neither paying compensation to the worker nor subject to an order to pay under the Act. The section's language is plain and cannot support the BRB's interpretation. The normal meaning of entitlement includes a right or benefit for which a person qualifies, regardless of whether the right or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Exxon Co., U.S.A. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Exxon Corp. v. Train","cite":"554 F.3d 1310","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/554/1310/","by":{"2":"46, 47"}},{"t":"case","label":"Husted v. A. Philip Randolph Inst.","cite":"138 S. Ct. 1833","y":2018,"id":"2017/16-980","sc":1,"sum":"A case in which the Court upheld Ohio's list-maintenance process against a challenge under under National Voter Registration Act of 1993 (NVRA) and the Help America Vote Act of 2002 (HAVA).","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Inland Steel Co. v. EPA","cite":"901 F.2d 1419","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/901/1419/","by":{"2":"23, 51","3":"14"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"2":"15, 28"}},{"t":"case","label":"Legal Envtl. Assistance Fdn., Inc. v. EPA","cite":"118 F.3d 1467","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/118/1467/","op":3,"by":{"2":"50"}},{"t":"case","label":"Levin v. United States","cite":"568 U.S. 503","y":2013,"id":"2012/11-1351","sc":1,"sum":"The Court held that the Gonzalez Act made an exception to the Federal Tort Claims Act by saying that a claim of the intentional tort of battery may be brought against an armed forces physician.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Los Angeles County Flood Control Dist. v. NRDC","cite":"568 U.S. 78","y":2013,"id":"2012/11-460","sc":1,"sum":"The Court found that transferring polluted water from one portion of a waterway to another portion of the same waterway did not constitute pollution under the Clean Water Act.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"op":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Metro. Edison Co. v. People Against Nuclear Energy","cite":"460 U.S. 766","y":1983,"id":"1982/81-2399","sc":1,"sum":"The NRC need not consider PANE's contentions.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Milwaukee & St. P.R. Co. v. Kellogg","cite":"94 U.S. 469","y":1876,"id":"scdb/1876-197","sc":1,"by":{"2":"21"}},{"t":"case","label":"Or. Nat. Res. Council v. U.S. Forest Serv.","cite":"834 F.2d 842","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/834/842/","by":{"2":"37, 38"}},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"op":3,"sum":"The Court held that it is the duty of the court system to harmonize statutes, and that barring one applicable statute by use of another represents a disregard of the law's intent of having cooperative statutes.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Rice v. Harken Exploration Co.","cite":"250 F.3d 264","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/250/264/","by":{"2":"47"}},{"t":"case","label":"Rubin v. Islamic Repub. of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"2":"23","3":"7"}},{"t":"case","label":"S.D. Warren Co. v. Me. Bd. of Envtl. Prot.","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"op":4,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"2":"28, 29"}},{"t":"case","label":"United States v. Ballard Oil Co. of Hartford","cite":"195 F.2d 369","y":1952,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/195/369/","by":{"2":"25"}},{"t":"case","label":"United States v. Esso Standard Oil Co. of Puerto Rico","cite":"375 F.2d 621","y":1967,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.2d/375/621/","by":{"2":"25, 26"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"United States v. Standard Oil Co.","cite":"384 U.S. 224","y":1966,"id":"1965/291","sc":1,"sum":"The Court held that the statute was meant to prevent pollution, and therefore must be read in a broader sense. The effect of the oil on the waterway is the same whether it was useable or not, so it should be treated the same way under the statute. The Court also held that there was legislative precedent for not creating a distinction between valuable and valueless substances deposited in waterways.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"United States v. Valley Camp Coal Co.","cite":"480 F.2d 616","y":1973,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/480/616/","by":{"2":"26"}},{"t":"case","label":"United States v. White Fuel Corp.","cite":"498 F.2d 619","y":1974,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/498/619/","by":{"2":"26"}},{"t":"case","label":"U.S. Steel Corp. v. Train","cite":"556 F.2d 822","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/556/822/","op":1,"by":{"2":"46"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Federal Cases: Air & Liquid Sys. Corp. v. DeVries","cite":"139 S. Ct. 986","y":2019,"id":"2018/17-1104","sc":1,"sum":"In the maritime tort context, a product manufacturer has a duty to warn when its product requires incorporation of a part, the manufacturer knows or has reason to know that the integrated product is likely to be dangerous for its intended uses, and the manufacturer has no reason to believe that the product’s users will realize that danger.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"2, 11"}},{"t":"case","label":"Culbertson v. Berryhill","cite":"139 S. Ct. 517","y":2019,"id":"2018/17-773","sc":1,"sum":"The Social Security Act’s fee cap of 25% of past-due benefits imposed on attorneys who successfully represent Title II benefit claimants in court proceedings applies only to fees for court representation and not to aggregate fees for both court and agency representation.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"13"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Peconic Baykeeper, Inc. v. Suffolk County","cite":"600 F.3d 180","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/600/180/","by":{"3":"21"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"7"}},{"t":"case","label":"Sierra Club v. BNSF Ry. Co.","cite":"2016 WL 6217108","y":2016,"court":"W.D. Wash. Oct. 25","by":{"3":"5"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"7"}},{"t":"case","label":"United States v. Lucas","cite":"516 F.3d 316","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/516/316/","by":{"3":"5"}},{"t":"usc","label":"33 U.S.C. § 407","url":"https://www.law.cornell.edu/uscode/text/33/407","by":{"3":"15"}},{"t":"usc","label":"33 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/33/1254","subs":["(c)"],"by":{"3":"15"}}]};